ALTER TABLE OGGETTI ADD PERCORSO VARCHAR(128);
ALTER TABLE DOMANDESTC MODIFY NUMEROISTANZA VARCHAR(35) ;
ALTER TABLE  MOVIMENTIALLEGATI ADD FLAG_PUBBLICA NUMERIC(1,0);
ALTER TABLE TIPIMOVIMENTO ADD FLAG_PUBBLICAALLEGATI NUMERIC(1,0);

CREATE INDEX IDX_MOV_CONTROMOV_001 ON MOVIMENTI_CONTROMOVIMENTI (IDCOMUNE,CODICEMOVIMENTO);
CREATE INDEX IDX_MOV_CONTROMOV_002 ON MOVIMENTI_CONTROMOVIMENTI (IDCOMUNE,CODICECONTROMOVIMENTO);


CREATE OR REPLACE ALGORITHM=TEMPTABLE VIEW VW_A_IMPORTI_NON_RIDOTTI as SELECT registrazioni.id as id, registrazioni.importo as importo_registrazione, ifnull(SUM(reg_io_assegnazioni.importo), 0) as incassato, registrazioni.importo - SUM(ifnull(reg_io_assegnazioni.importo, 0)) as saldo, registrazioni.idcomune as idcomune FROM registrazioni LEFT OUTER JOIN registrazioni_importi LEFT OUTER JOIN reg_io_assegnazioni ON registrazioni_importi.idcomune = reg_io_assegnazioni.idcomune AND registrazioni_importi.id = reg_io_assegnazioni.fk_riid ON registrazioni.idcomune=registrazioni_importi.idcomune  AND registrazioni.id=registrazioni_importi.fk_rgid WHERE (registrazioni_importi.flag_nonprevincassi = 0 or registrazioni_importi.flag_nonprevincassi  is NULL)  GROUP BY registrazioni.id, registrazioni.importo, registrazioni.software, registrazioni.idcomune;
CREATE OR REPLACE ALGORITHM=TEMPTABLE VIEW VW_A_IMPORTI_RIDOTTI as SELECT registrazioni.id as id, registrazioni.importo as importo_registrazione, ifnull(SUM(reg_io_assegnazioni.importo), 0) as incassato, SUM(registrazioni_importi.importo) - SUM(ifnull(reg_io_assegnazioni.importo, 0)) as saldo, registrazioni.idcomune as idcomune FROM registrazioni LEFT OUTER JOIN registrazioni_importi LEFT OUTER JOIN reg_io_assegnazioni ON registrazioni_importi.idcomune = reg_io_assegnazioni.idcomune AND registrazioni_importi.id = reg_io_assegnazioni.fk_riid ON registrazioni.idcomune=registrazioni_importi.idcomune  AND registrazioni.id=registrazioni_importi.fk_rgid WHERE (registrazioni_importi.flag_nonprevincassi = 1 or registrazioni_importi.flag_nonprevincassi  is NULL)  GROUP BY registrazioni.id, registrazioni.importo, registrazioni.software, registrazioni.idcomune;
CREATE OR REPLACE ALGORITHM=MERGE VIEW VW_ALBEROPROC AS SELECT ALBEROPROC.IDCOMUNE,ALBEROPROC.SOFTWARE,ALBEROPROC.SC_ID,ALBEROPROC.SC_CODICE,ALBEROPROC.SC_PADRE,CONCAT(CONCAT(CONCAT(CONCAT(CONCAT(CASE ISNULL(ALBEROPROC_L4.SC_DESCRIZIONE) WHEN 1 THEN  ''  ELSE CONCAT(ALBEROPROC_L4.SC_DESCRIZIONE  , ' - ' ) END ),CASE ISNULL(ALBEROPROC_L3.SC_DESCRIZIONE) WHEN 1 THEN  ''  ELSE CONCAT(ALBEROPROC_L3.SC_DESCRIZIONE, ' - ' ) END ),CASE ISNULL(ALBEROPROC_L2.SC_DESCRIZIONE) WHEN 1  THEN  '' ELSE CONCAT(ALBEROPROC_L2.SC_DESCRIZIONE  , ' - ' ) END ),CASE ISNULL(ALBEROPROC_L1.SC_DESCRIZIONE) WHEN 1 THEN '' ELSE CONCAT(ALBEROPROC_L1.SC_DESCRIZIONE , ' - ' ) END ), ALBEROPROC.SC_DESCRIZIONE) AS SC_DESCRIZIONE,CONCAT(CONCAT(CONCAT(CONCAT(CASE ISNULL(ALBEROPROC_L4.SC_DESCRIZIONE) WHEN 1 THEN  ''  ELSE CONCAT(ALBEROPROC_L4.SC_DESCRIZIONE, ' - ' ) END ),CASE ISNULL(ALBEROPROC_L3.SC_DESCRIZIONE) WHEN 1  THEN  '' ELSE CONCAT(ALBEROPROC_L3.SC_DESCRIZIONE, ' - ' ) END	),CASE ISNULL(ALBEROPROC_L2.SC_DESCRIZIONE) WHEN 1  THEN '' ELSE CONCAT(ALBEROPROC_L2.SC_DESCRIZIONE, ' - ' ) END),CASE ISNULL(ALBEROPROC_L1.SC_DESCRIZIONE) WHEN 1 THEN '' ELSE CONCAT(ALBEROPROC_L1.SC_DESCRIZIONE, ' - ' ) END ) AS SC_DESCRIZIONEPADRE,ALBEROPROC.SC_DESCRIZIONE AS SC_DESCRIZIONEBREVE,ALBEROPROC.SC_ORDINE AS ORDINE0,IFNULL(ALBEROPROC_L1.SC_ORDINE,0) AS ORDINE1, IFNULL(ALBEROPROC_L2.SC_ORDINE,0) AS ORDINE2, IFNULL(ALBEROPROC_L3.SC_ORDINE,0) AS ORDINE3, IFNULL(ALBEROPROC_L4.SC_ORDINE,0) AS ORDINE4, (CASE ALBEROPROC.FKCODICEMERCATO WHEN NULL THEN ( CASE ALBEROPROC_L1.FKCODICEMERCATO WHEN NULL THEN ( CASE ALBEROPROC_L2.FKCODICEMERCATO WHEN NULL THEN (CASE ALBEROPROC_L3.FKCODICEMERCATO WHEN NULL THEN ALBEROPROC_L4.FKCODICEMERCATO ELSE ALBEROPROC_L3.FKCODICEMERCATO END ) ELSE ALBEROPROC_L2.FKCODICEMERCATO END ) ELSE ALBEROPROC_L1.FKCODICEMERCATO END ) ELSE ALBEROPROC.FKCODICEMERCATO END ) AS FKCODICEMERCATO,(CASE ALBEROPROC.FKIDMERCATIUSO WHEN NULL THEN (CASE ALBEROPROC_L1.FKIDMERCATIUSO WHEN NULL THEN (CASE ALBEROPROC_L2.FKIDMERCATIUSO WHEN NULL THEN (CASE ALBEROPROC_L3.FKIDMERCATIUSO WHEN NULL THEN ALBEROPROC_L4.FKIDMERCATIUSO ELSE ALBEROPROC_L3.FKIDMERCATIUSO END) ELSE ALBEROPROC_L2.FKIDMERCATIUSO END) ELSE ALBEROPROC_L1.FKIDMERCATIUSO END) ELSE ALBEROPROC.FKIDMERCATIUSO END) AS FKIDMERCATIUSO, ALBEROPROC.SC_ATTIVO, ALBEROPROC.PROGRESSIVOISTANZE FROM ALBEROPROC LEFT JOIN ALBEROPROC ALBEROPROC_L1 ON ALBEROPROC_L1.IDCOMUNE = ALBEROPROC.IDCOMUNE AND ALBEROPROC_L1.SOFTWARE = ALBEROPROC.SOFTWARE AND ALBEROPROC_L1.SC_CODICE = SUBSTRING(ALBEROPROC.SC_CODICE,1,(LENGTH(ALBEROPROC.SC_CODICE)-2)) LEFT JOIN ALBEROPROC ALBEROPROC_L2 ON ALBEROPROC_L2.IDCOMUNE = ALBEROPROC_L1.IDCOMUNE AND ALBEROPROC_L2.SOFTWARE = ALBEROPROC_L1.SOFTWARE AND ALBEROPROC_L2.SC_CODICE = SUBSTRING(ALBEROPROC_L1.SC_CODICE,1,(LENGTH(ALBEROPROC_L1.SC_CODICE)-2)) LEFT JOIN ALBEROPROC ALBEROPROC_L3 ON ALBEROPROC_L3.IDCOMUNE = ALBEROPROC_L2.IDCOMUNE AND ALBEROPROC_L3.SOFTWARE = ALBEROPROC_L2.SOFTWARE AND ALBEROPROC_L3.SC_CODICE = SUBSTRING(ALBEROPROC_L2.SC_CODICE,1,(LENGTH(ALBEROPROC_L2.SC_CODICE)-2)) LEFT JOIN ALBEROPROC ALBEROPROC_L4 ON ALBEROPROC_L4.IDCOMUNE = ALBEROPROC_L3.IDCOMUNE AND ALBEROPROC_L4.SOFTWARE = ALBEROPROC_L3.SOFTWARE AND ALBEROPROC_L4.SC_CODICE = SUBSTRING(ALBEROPROC_L3.SC_CODICE,1,(LENGTH(ALBEROPROC_L3.SC_CODICE)-2));
CREATE OR REPLACE ALGORITHM=TEMPTABLE VIEW VW_ANAGRAFEINTERDETTI as select idcomune, codiceanagrafe, max(datascadenza) as datascadenza from  scadenze where datascadenza>sysdate() and categoria='I' group by idcomune, codiceanagrafe;
CREATE OR REPLACE ALGORITHM=MERGE VIEW VW_ANAGRAFE_LOCALIZZAZIONI as SELECT ANAGRAFE.IDCOMUNE, ANAGRAFE.CODICEANAGRAFE, TRIM( CONCAT_WS('', ANAGRAFE.NOMINATIVO,' ', ANAGRAFE.NOME))  as NOMINATIVO, ANAGRAFE.INDIRIZZO as INDIRIZZO_RESIDENZA, CONCAT_WS('', case ifnull(ANAGRAFE.CAP, '0') when '0' then '' ELSE  CONCAT_WS('', ANAGRAFE.CAP, ', ') end , case ifnull(COMUNI_RESIDENZA.COMUNE, '0') when '0' then '' ELSE  CONCAT_WS('', COMUNI_RESIDENZA.COMUNE, '') end , case ifnull(ANAGRAFE.CITTA, '0') when '0' then '' ELSE  CONCAT_WS('',', ', ANAGRAFE.CITTA, '') end , case ifnull(ANAGRAFE.PROVINCIA, '0') when '0' then '' ELSE  CONCAT_WS('',' (', ANAGRAFE.PROVINCIA, ')') end ) as LOCALIZZAZIONE_RESIDENZA, ANAGRAFE.INDIRIZZOCORRISPONDENZA as INDIRIZZO_CORRISPONDENZA, CONCAT_WS('', case ifnull(ANAGRAFE.CAPCORRISPONDENZA, '0') when '0' then '' ELSE  CONCAT_WS('', ANAGRAFE.CAPCORRISPONDENZA, ', ') end , case ifnull(COMUNI_CORRISPONDENZA.COMUNE, '0') when '0' then '' ELSE  CONCAT_WS('', COMUNI_CORRISPONDENZA.COMUNE, '') end , case ifnull(ANAGRAFE.CITTACORRISPONDENZA, '0') when '0' then '' ELSE  CONCAT_WS('',', ', ANAGRAFE.CITTACORRISPONDENZA, '') end , case ifnull(ANAGRAFE.PROVINCIACORRISPONDENZA, '0') when '0' then '' ELSE  CONCAT_WS('',' (', ANAGRAFE.PROVINCIACORRISPONDENZA, ')') end ) as LOCALIZZAZIONE_CORRISPONDENZA, case ifnull(ANAGRAFE.INDIRIZZOCORRISPONDENZA, '0') when '0' then 0 ELSE 1 end as IS_CORRISPONDENZA FROM ANAGRAFE LEFT OUTER JOIN COMUNI COMUNI_RESIDENZA ON ANAGRAFE.COMUNERESIDENZA = COMUNI_RESIDENZA.CODICECOMUNE LEFT OUTER JOIN COMUNI COMUNI_CORRISPONDENZA ON ANAGRAFE.COMUNECORRISPONDENZA = COMUNI_CORRISPONDENZA.CODICECOMUNE;
CREATE OR REPLACE ALGORITHM=TEMPTABLE VIEW VW_A_REG_IMPORTI_DEBITI as SELECT REGISTRAZIONI.ID as ID_REGISTRAZIONE, REGISTRAZIONI.SOFTWARE, REGISTRAZIONI.IDCOMUNE, REGISTRAZIONI_IMPORTI.ID, REGISTRAZIONI_IMPORTI.IMPORTO, REGISTRAZIONI_IMPORTI.NR_RATA as RATA, SUM(REG_IO_ASSEGNAZIONI.IMPORTO) as INCASSATO FROM REGISTRAZIONI_IMPORTI LEFT OUTER JOIN REG_IO_ASSEGNAZIONI ON REGISTRAZIONI_IMPORTI.IDCOMUNE=REG_IO_ASSEGNAZIONI.IDCOMUNE  AND REGISTRAZIONI_IMPORTI.ID=REG_IO_ASSEGNAZIONI.FK_RIID, REGISTRAZIONI WHERE REGISTRAZIONI.IDCOMUNE = REGISTRAZIONI_IMPORTI.IDCOMUNE AND REGISTRAZIONI.ID = REGISTRAZIONI_IMPORTI.FK_RGID AND REGISTRAZIONI_IMPORTI.FLAG_NONPREVINCASSI = 0 GROUP BY REGISTRAZIONI.ID, REGISTRAZIONI_IMPORTI.ID, REGISTRAZIONI_IMPORTI.IMPORTO, REGISTRAZIONI_IMPORTI.NR_RATA, REGISTRAZIONI.SOFTWARE, REGISTRAZIONI.IDCOMUNE HAVING ifnull(SUM(REG_IO_ASSEGNAZIONI.IMPORTO),  0) < REGISTRAZIONI_IMPORTI.IMPORTO;
CREATE OR REPLACE ALGORITHM=TEMPTABLE VIEW VW_A_REGISTRAZIONI_DEBITI as SELECT id_REGISTRAZIONE, IDCOMUNE, SOFTWARE, rata as rata_non_pagata, SUM(importo) as importo_rata, ifnull(SUM(incassato),  0) as incassato_rata, (SUM(IMPORTO) - ifnull(SUM(incassato),  0)) as DA_INCASSARE FROM  VW_A_REG_IMPORTI_DEBITI 	 GROUP BY ID_REGISTRAZIONE, SOFTWARE, IDCOMUNE,rata;
CREATE OR REPLACE ALGORITHM=TEMPTABLE View VW_A_SALDO_RIDOTTI as SELECT registrazioni.id as id, SUM(registrazioni_importi.importo) saldo, registrazioni.idcomune as idcomune FROM  registrazioni,  registrazioni_importi WHERE registrazioni_importi.idcomune = registrazioni.idcomune and registrazioni_importi.fk_rgid = registrazioni.id and registrazioni_importi.flag_nonprevincassi = 1 GROUP BY registrazioni.id, registrazioni.idcomune;
CREATE OR REPLACE ALGORITHM=TEMPTABLE View VW_ASSENZECONCESSIONARI as SELECT COUNT(*) as numero_assenze, mercati.codicemercato, MERCATI.descrizione as MERCATO, mercati_uso.id as codiceuso, mercati_uso.descrizione as USO, mercati_d.idposteggio, MERCATI_D.codiceposteggio as POSTEGGIO, anagrafe.codiceanagrafe, ANAGRAFE.NOMINATIVO, ANAGRAFE.NOME, mercatipresenze_t.anno, mercatipresenze_t.software, mercatipresenze_t.idcomune FROM  MERCATIPRESENZE_D,  ANAGRAFE,  MERCATI,  MERCATI_USO,  MERCATI_D,  MERCATIPRESENZE_T WHERE MERCATIPRESENZE_D.IDCOMUNE = mercatipresenze_t.idcomune and MERCATIPRESENZE_D.fkidtestata = mercatipresenze_t.id and mercatipresenze_d.idcomune = anagrafe.idcomune and mercatipresenze_d.codiceconcessionario = anagrafe.codiceanagrafe and MERCATI.IDCOMUNE = mercatipresenze_T.idcomune and mercati.codicemercato = mercatipresenze_T.fkcodicemercato and MERCATI_USO.IDCOMUNE = MERCATIPRESENZE_T.IDCOMUNE and MERCATI_USO.id = MERCATIPRESENZE_T.fkidmercatiuso and mercati_d.idcomune = MERCATIPRESENZE_D.idcomune and mercati_d.idposteggio = mercatipresenze_d.fkidposteggio and codiceconcessionario  is not  NULL and ( ( MERCATIPRESENZE_D.CODICEANAGRAFE <> CODICECONCESSIONARIO) or MERCATIPRESENZE_D.CODICEANAGRAFE  is  NULL ) and ( flag_assenza_giust  is  NULL or flag_assenza_giust = 0) GROUP BY anagrafe.nominativo, anagrafe.nomE, MERCATI.descrizione, mercati_uso.descrizione, mercati_d.idposteggio, MERCATI_D.codiceposteggio, mercati.codicemercato, mercatipresenze_t.anno, mercatipresenze_t.software, mercatipresenze_t.idcomune, anagrafe.codiceanagrafe, mercati_uso.id ORDER BY mercato,uso, posteggio, nominativo,nome;
CREATE OR REPLACE ALGORITHM=TEMPTABLE View VW_BATCH_SCADENZARIO as SELECT mdf.codicemovimento as id,sysdate() as dataelaborazione,mdf.idcomune as idcomune,istanze.software as software,mdf.codiceistanza as codiceistanza,mf.codicemovimento as codicemovimento,ifnull(mf.movimento, tmf.movimento) as descrmovimento,mdf.tipomovimento as tipomovimentodafare,ifnull(mdf.movimento, tm.movimento) as descrmovimentodafare,mdf.codiceinventario as codiceinventario,mdf.codiceamministrazione as CODICEAMMINISTRAZIONE,mdf.data_scadenza as datascadenza FROM  movimenti mdf INNER JOIN istanze ON istanze.idcomune       =mdf.idcomune AND istanze.codiceistanza =mdf.codiceistanza INNER JOIN tipimovimento tm ON tm.idcomune       =mdf.idcomune AND tm.tipomovimento =mdf.tipomovimento LEFT JOIN movimenti_contromovimenti mcm ON mcm.idcomune              =mdf.idcomune AND mcm.codicecontromovimento=mdf.codicemovimento LEFT JOIN movimenti mf ON mf.idcomune              =mcm.idcomune and mf.codicemovimento      =mcm.codicemovimento left join tipimovimento tmf on tmf.idcomune=mf.idcomune and  tmf.tipomovimento=mf.tipomovimento WHERE mdf.data  is  NULL and (mdf.flag_disabilitato  is  NULL or mdf.flag_disabilitato = 0);
CREATE OR REPLACE ALGORITHM=MERGE View VW_CCICT_DESTINAZIONI as SELECT CC_ICALCOLOTOT.IDCOMUNE, CC_ICALCOLOTOT.ID as CCICT_ID, CC_DESTINAZIONI.ID as CCDE_ID, CC_DESTINAZIONI.DESTINAZIONE FROM  CC_DESTINAZIONI,  ISTANZE,  CC_ICALCOLOTOT WHERE ISTANZE.IDCOMUNE = CC_ICALCOLOTOT.IDCOMUNE and ISTANZE.CODICEISTANZA = CC_ICALCOLOTOT.CODICEISTANZA and CC_DESTINAZIONI.IDCOMUNE = CC_ICALCOLOTOT.IDCOMUNE and CC_DESTINAZIONI.FK_OCCBDE_ID = CC_ICALCOLOTOT.FK_OCCBDE_ID and CC_DESTINAZIONI.SOFTWARE = ISTANZE.SOFTWARE;
CREATE OR REPLACE ALGORITHM=MERGE View VW_CCICT_TIPIINTERVENTO as SELECT CC_ICALCOLOTOT.IDCOMUNE, CC_ICALCOLOTOT.ID as CCICT_ID, CC_TIPOINTERVENTO.ID as CCTI_ID, CC_TIPOINTERVENTO.INTERVENTO FROM  CC_TIPOINTERVENTO,  ISTANZE,  CC_ICALCOLOTOT WHERE ISTANZE.IDCOMUNE = CC_ICALCOLOTOT.IDCOMUNE and ISTANZE.CODICEISTANZA = CC_ICALCOLOTOT.CODICEISTANZA and CC_TIPOINTERVENTO.IDCOMUNE = CC_ICALCOLOTOT.IDCOMUNE and CC_TIPOINTERVENTO.FK_OCCBTI_ID = CC_ICALCOLOTOT.FK_OCCBTI_ID and CC_TIPOINTERVENTO.SOFTWARE = ISTANZE.SOFTWARE;
CREATE OR REPLACE ALGORITHM=MERGE View VW_CONCESSIONIATTIVE as SELECT istanze.idcomune, istanze.software, autorizzazioni.id as codiceconcessione, istanze.codiceistanza, autorizzazioni.fk_codiceanagrafe as codicetitolare, case  ifnull(istanze.codicetitolarelegale, -1) when -1 then istanze.codicerichiedente ELSE istanze. codicetitolarelegale end as codiceoccupante, autorizzazioni_concessioni.fk_codicemercato, autorizzazioni_concessioni.fk_idmercatiuso, autorizzazioni_concessioni.fk_idposteggio FROM  istanze,  autorizzazioni,  autorizzazioni_concessioni WHERE autorizzazioni.idcomune = istanze.idcomune and autorizzazioni.fkidistanza = istanze.codiceistanza and autorizzazioni.idcomune = autorizzazioni_concessioni.idcomune and AUTORIZZAZIONI.id = AUTORIZZAZIONI_CONCESSIONI.FK_IDAUT_ATTUALE and (autorizzazioni.flag_attiva = 1 and (AUTORIZZAZIONI.DATA_CESSAZIONE >= sysdate() or autorizzazioni.data_cessazione  is  NULL));
CREATE OR REPLACE ALGORITHM=MERGE View VW_I_ATTIVITAAUTORIZZAZIONI as SELECT I_ATTIVITA.ID as I_IDATTIVITA, AUTORIZZAZIONI.AUTORIZNUMERO, AUTORIZZAZIONI.AUTORIZDATA, AUTORIZZAZIONI.AUTORIZDATAREGISTR, AUTORIZZAZIONI.AUTORIZRESPONSABILE, AUTORIZZAZIONI.FKIDREGISTRO, AUTORIZZAZIONI.FKIDISTANZA, AUTORIZZAZIONI.IDCOMUNE, AUTORIZZAZIONI.CODICEMOVIMENTO, AUTORIZZAZIONI.ID FROM  I_ATTIVITA,  AUTORIZZAZIONI,  ISTANZE WHERE ISTANZE.IDCOMUNE = I_ATTIVITA.IDCOMUNE and ISTANZE.FK_IDI_ATTIVITA = I_ATTIVITA.ID and AUTORIZZAZIONI.IDCOMUNE = ISTANZE.IDCOMUNE and AUTORIZZAZIONI.FKIDISTANZA = ISTANZE.CODICEISTANZA;
CREATE OR REPLACE ALGORITHM=MERGE View VW_I_ATTIVITAINFORMAZIONI as SELECT I_ATTIVITA.ID as I_IDATTIVITA, ISTANZEATTIVITA.CODICEISTANZA, ISTANZEATTIVITA.CODICEATTIVITA, ISTANZEATTIVITA.METRIQ, ISTANZEATTIVITA.NOTE, ISTANZEATTIVITA.IDCOMUNE, ISTANZEATTIVITA.SOFTWARE, ISTANZEATTIVITA.IDATTIVITA FROM  I_ATTIVITA,  ISTANZEATTIVITA WHERE ISTANZEATTIVITA.IDCOMUNE = I_ATTIVITA.IDCOMUNE and ISTANZEATTIVITA.CODICEISTANZA = I_ATTIVITA.CODICEISTANZAULTIMA;
CREATE OR REPLACE ALGORITHM=MERGE View VW_I_ATTIVITALISTA as SELECT I_ATTIVITA.CODICEISTANZAULTIMA as I_CODICEISTANZAULTIMA, I_ATTIVITA.ID as I_IDATTIVITA, I_ATTIVITA.IDCOMUNE, I_ATTIVITA.ATTIVA, I_ATTIVITA.OPERANTE, ISTANZE.SOFTWARE, I_ATTIVITA.DENOMINAZIONE, ISTANZE.NUMEROISTANZA, ISTANZE.CODICERICHIEDENTE, CONCAT_WS('', T_RICHIEDENTE.NOMINATIVO,' ', T_RICHIEDENTE.NOME) as RICHIEDENTE, TRIM( CONCAT_WS('', T_RICHIEDENTE.CODICEFISCALE,' ', T_RICHIEDENTE.PARTITAIVA))  as CF_PIVA_RICHIEDENTE, ISTANZE.FKCODICESOGGETTO, TIPISOGGETTO.TIPOSOGGETTO, ISTANZE.CODICECOMUNE, ISTANZE.CODICETITOLARELEGALE, TRIM( CONCAT_WS('', T_AZIENDARICHIEDENTE.NOMINATIVO,' ', T_AZIENDARICHIEDENTE.NOME))  as AZIENDARICHIEDENTE, TRIM( CONCAT_WS('', T_AZIENDARICHIEDENTE.CODICEFISCALE,' ', T_AZIENDARICHIEDENTE.PARTITAIVA))  as CF_PIVA_AZIENDARICHIEDENTE, ISTANZESTRADARIO.CODICESTRADARIO, CONCAT_WS('', STRADARIO.PREFISSO,' ', STRADARIO.DESCRIZIONE,',', ifnull(ISTANZESTRADARIO.CIVICO,''), ifnull(ISTANZESTRADARIO.COLORE, '')) as LOCALIZZAZIONE, ISTANZESTRADARIO.CIVICO FROM ISTANZE LEFT OUTER JOIN ANAGRAFE T_AZIENDARICHIEDENTE ON ISTANZE.IDCOMUNE=T_AZIENDARICHIEDENTE.IDCOMUNE  AND ISTANZE.CODICETITOLARELEGALE=T_AZIENDARICHIEDENTE.CODICEANAGRAFE  LEFT OUTER JOIN TIPISOGGETTO ON ISTANZE.IDCOMUNE=TIPISOGGETTO.IDCOMUNE  AND ISTANZE.FKCODICESOGGETTO=TIPISOGGETTO.CODICETIPOSOGGETTO, I_ATTIVITA, ANAGRAFE T_RICHIEDENTE, ISTANZESTRADARIO, STRADARIO WHERE ISTANZE.IDCOMUNE = I_ATTIVITA.IDCOMUNE AND ISTANZE.CODICEISTANZA = I_ATTIVITA.CODICEISTANZAULTIMA AND T_RICHIEDENTE.IDCOMUNE = ISTANZE.IDCOMUNE AND T_RICHIEDENTE.CODICEANAGRAFE = ISTANZE.CODICERICHIEDENTE AND ISTANZESTRADARIO.IDCOMUNE = ISTANZE.IDCOMUNE AND ISTANZESTRADARIO.CODICEISTANZA = ISTANZE.CODICEISTANZA AND ISTANZESTRADARIO.PRIMARIO = 1 AND STRADARIO.IDCOMUNE = ISTANZESTRADARIO.IDCOMUNE AND STRADARIO.CODICESTRADARIO = ISTANZESTRADARIO.CODICESTRADARIO ;
CREATE OR REPLACE ALGORITHM=MERGE View VW_I_ATTIVITALOCALIZZAZIONI as SELECT I_ATTIVITA.ID as I_IDATTIVITA, ISTANZESTRADARIO.ID, ISTANZESTRADARIO.CODICEISTANZA, ISTANZESTRADARIO.CODICESTRADARIO, ISTANZESTRADARIO.CIVICO, ISTANZESTRADARIO.COLORE, ISTANZESTRADARIO.NOTE, ISTANZESTRADARIO.PRIMARIO, ISTANZESTRADARIO.IDCOMUNE, ISTANZESTRADARIO.FRAZIONE, ISTANZESTRADARIO.CIRCOSCRIZIONE, ISTANZESTRADARIO.CAP, ISTANZESTRADARIO.KM, ISTANZESTRADARIO.ESPONENTE, ISTANZESTRADARIO.SCALA, ISTANZESTRADARIO.INTERNO, ISTANZESTRADARIO.ESPONENTEINTERNO, ISTANZESTRADARIO.FABBRICATO, ISTANZESTRADARIO.CODICECIVICO, ISTANZESTRADARIO.FKIDMAPPALE, ISTANZESTRADARIO.VALIDO FROM  I_ATTIVITA,  ISTANZESTRADARIO WHERE ISTANZESTRADARIO.IDCOMUNE = I_ATTIVITA.IDCOMUNE and ISTANZESTRADARIO.CODICEISTANZA = I_ATTIVITA.CODICEISTANZAULTIMA;
CREATE OR REPLACE ALGORITHM=MERGE View VW_I_ATTIVITAMAPPALI as SELECT I_ATTIVITA.ID as I_IDATTIVITA, ISTANZEMAPPALI.IDMAPPALE, ISTANZEMAPPALI.FOGLIO, ISTANZEMAPPALI.PARTICELLA, ISTANZEMAPPALI.SUB, ISTANZEMAPPALI.FKCODICEISTANZA, ISTANZEMAPPALI.PRIMARIO, ISTANZEMAPPALI.IDCOMUNE, ISTANZEMAPPALI.CODICECATASTO, ISTANZEMAPPALI.SEZIONE, ISTANZEMAPPALI.UNITAIMMOB FROM  I_ATTIVITA,  ISTANZEMAPPALI WHERE ISTANZEMAPPALI.IDCOMUNE = I_ATTIVITA.IDCOMUNE and ISTANZEMAPPALI.FKCODICEISTANZA = I_ATTIVITA.CODICEISTANZAULTIMA and ISTANZEMAPPALI.FOGLIO  is not  NULL;
CREATE OR REPLACE ALGORITHM=MERGE View VW_I_ATTIVITAORARI as SELECT I_ATTIVITA.ID as I_IDATTIVITA, ORARIAPERTURATESTATA.ID, ORARIAPERTURATESTATA.IDCOMUNE, ORARIAPERTURATESTATA.PERIODODA, ORARIAPERTURATESTATA.PERIODOA, ORARIAPERTURATESTATA.CODICEISTANZA, ORARIAPERTURATESTATA.FKTOID FROM  I_ATTIVITA,  ORARIAPERTURATESTATA WHERE ORARIAPERTURATESTATA.IDCOMUNE = I_ATTIVITA.IDCOMUNE and ORARIAPERTURATESTATA.CODICEISTANZA = I_ATTIVITA.CODICEISTANZAULTIMA;
CREATE OR REPLACE ALGORITHM=TEMPTABLE View VW_I_ATTIVITASOGGETTICOLLEGATI as SELECT I_ATTIVITA.ID as I_IDATTIVITA, ISTANZERICHIEDENTI.CODICEISTANZA, ISTANZERICHIEDENTI.CODICERICHIEDENTE, ISTANZERICHIEDENTI.CODICETIPOSOGGETTO, ISTANZERICHIEDENTI.IDCOMUNE, ISTANZERICHIEDENTI.CODICEANAGRAFECOLL FROM  I_ATTIVITA,  ISTANZERICHIEDENTI WHERE ISTANZERICHIEDENTI.IDCOMUNE = I_ATTIVITA.IDCOMUNE and ISTANZERICHIEDENTI.CODICEISTANZA = I_ATTIVITA.CODICEISTANZAULTIMA UNION Select I_ATTIVITA.ID as I_IDATTIVITA, ISTANZE.CODICEISTANZA, ISTANZE.CODICERICHIEDENTE,  ISTANZE.FKCODICESOGGETTO as CODICETIPOSOGGETTO, ISTANZE.IDCOMUNE,  ISTANZE.CODICETITOLARELEGALE as CODICEANAGRAFECOLL From I_ATTIVITA,  ISTANZE Where ISTANZE.IDCOMUNE = I_ATTIVITA.IDCOMUNE and ISTANZE.CODICEISTANZA = I_ATTIVITA.CODICEISTANZAULTIMA UNION Select I_ATTIVITA.ID as I_IDATTIVITA, ISTANZE.CODICEISTANZA, ISTANZE.CODICETITOLARELEGALE as CODICERICHIEDENTE,  -1 as CODICETIPOSOGGETTO, ISTANZE.IDCOMUNE,  -1 as CODICEANAGRAFECOLL From I_ATTIVITA,  ISTANZE Where ISTANZE.IDCOMUNE = I_ATTIVITA.IDCOMUNE and ISTANZE.CODICEISTANZA = I_ATTIVITA.CODICEISTANZAULTIMA and ISTANZE.CODICETITOLARELEGALE is not null;
CREATE OR REPLACE ALGORITHM=TEMPTABLE View VW_ISTANZECONCESSIONILISTA AS SELECT AUTORIZZAZIONI.IDCOMUNE,AUTORIZZAZIONI.FK_CAUSALE_ACQUISIZIONE as ICONC_CODICECAUSALE,AUTORIZZAZIONI.DATA_CESSAZIONE as DATA_STORICO,ISTANZE.SOFTWARE,ISTANZE.CODICEISTANZA as IST_CODICEISTANZA,ISTANZE.NUMEROISTANZA as IST_NUMEROISTANZA,istanze.codicerichiedente as ist_codicerichiedente,AUTORIZZAZIONI.ID as CONC_ID,AUTORIZZAZIONI.AUTORIZNUMERO as CONC_NUMERO,AUTORIZZAZIONI.AUTORIZDATA as CONC_DATARILASCIO,AUTORIZZAZIONI.AUTORIZDATA as DATARILASCIO,AUTORIZZAZIONI_CONCESSIONI.DATASCADENZA as CONC_DATASCADENZA,AUTORIZZAZIONI_CONCESSIONI.FK_TIPOCONCESSIONE as CONC_CODICETIPO,CONCESSIONITIPI.DESCRIZIONE as CONC_TIPO,AUTORIZZAZIONI_CONCESSIONI.STAGIONALEA as CONC_STAGIONALEA,AUTORIZZAZIONI_CONCESSIONI.STAGIONALEDA as CONC_STAGIONALEDA,AUTORIZZAZIONI.FLAG_ATTIVA as CONC_ATTIVA,AUTORIZZAZIONI.FK_CODICEANAGRAFE as CONC_CODICETITOLARE,CONCAT_WS('',TITOLARE.NOMINATIVO,' ',TITOLARE.NOME) as CONC_TITOLARE,titolare.codicefiscale as conc_tit_cf,TITOLARE.PARTITAIVA as CONC_TIT_PIVA,TITOLARE.TIPOANAGRAFE as CONC_TIT_TIPOANAGRAFE,AUT_COLLEGATA.AUTORIZNUMERO as AUT_NUMERO,AUT_COLLEGATA.AUTORIZDATA as AUT_DATA,AUT_COLLEGATA.AUTORIZDATA,AUT_COLLEGATA.FKIDREGISTRO as AUT_CODREGISTRO,TIPOLOGIAREGISTRI.TR_DESCRIZIONE as AUT_REGISTRO,CONCAT_WS('',IST_RICHIEDENTE.NOMINATIVO,' ',IST_RICHIEDENTE.NOME) as IST_NOMINATIVO,IST_RICHIEDENTE.TIPOANAGRAFE as IST_RIC_TIPOANAGRAFE,CONCAT_WS('',IST_AZIENDA.NOMINATIVO,' ',IST_AZIENDA.NOME) as IST_NOMINATIVOAZIENDA,IST_AZIENDA.TIPOANAGRAFE as IST_AZI_TIPOANAGRAFE,ist_richiedente.codicefiscale as ist_codicefiscale,IST_RICHIEDENTE.PARTITAIVA as IST_PARTITAIVA,CAUS_ATTUALE.DESCRIZIONE as ICONC_CAUSALE,AUTORIZZAZIONI.FK_CAUSALE_CESSAZIONE as ICONC_CODICECAUSALESTORICO,CAUS_STORICO.DESCRIZIONE as ICONC_CAUSALESTORICO,AUTORIZZAZIONI_CONCESSIONI.FK_CODICEMERCATO as CONC_IDMERCATO,MERCATI.DESCRIZIONE as CONC_MERCATO,MERCATI.ATTIVO as MERC_ATTIVO,AUTORIZZAZIONI_CONCESSIONI.FK_IDPOSTEGGIO as CONC_IDPOSTEGGIO,MERCATI_D.CODICEPOSTEGGIO as CONC_POSTEGGIO,MERCATI_D.LARGHEZZA as CONC_POS_LARGHEZZA,MERCATI_D.LUNGHEZZA as CONC_POS_LUNGHEZZA,MERCATI_D.SUPERFICIE as CONC_POS_SUPERFICIE,MERCATI_D.FKCODICETIPOSPAZIO as POST_IDTIPOSPAZIO,POSTEGGITIPOSPAZIO.TIPOSPAZIO as POST_TIPOSPAZIO,AUTORIZZAZIONI_CONCESSIONI.FK_IDMERCATIUSO as CONC_IDMERCATIUSO,MERCATI_USO.DESCRIZIONE as CONC_DESCRIZIONEUSO,MERCATI_USO.PESO as PESO_MERCATO,MERCATI_USO.FKCODICEUSO as MERC_IDUSO FROM AUTORIZZAZIONI_CONCESSIONI LEFT OUTER JOIN AUTORIZZAZIONI AUT_COLLEGATA ON AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE=AUT_COLLEGATA.IDCOMUNE  AND AUTORIZZAZIONI_CONCESSIONI.FK_IDAUT_COLLEGATA=AUT_COLLEGATA.id,AUTORIZZAZIONI LEFT OUTER JOIN TIPOLOGIAREGISTRI ON AUTORIZZAZIONI.IDCOMUNE=TIPOLOGIAREGISTRI.IDCOMUNE  AND AUTORIZZAZIONI.FKIDREGISTRO=TIPOLOGIAREGISTRI.TR_ID  LEFT OUTER JOIN CONCESSIONICAUSALI CAUS_STORICO ON AUTORIZZAZIONI.IDCOMUNE=CAUS_STORICO.IDCOMUNE  AND AUTORIZZAZIONI.FK_CAUSALE_CESSAZIONE=CAUS_STORICO.CODICECAUSALE,MERCATI_D LEFT OUTER JOIN POSTEGGITIPOSPAZIO ON MERCATI_D.IDCOMUNE=POSTEGGITIPOSPAZIO.IDCOMUNE  AND MERCATI_D.FKCODICETIPOSPAZIO=POSTEGGITIPOSPAZIO.CODICE,ISTANZE LEFT OUTER JOIN ANAGRAFE IST_AZIENDA ON ISTANZE.IDCOMUNE=IST_AZIENDA.IDCOMUNE  AND ISTANZE.CODICETITOLARELEGALE=IST_AZIENDA.CODICEANAGRAFE,CONCESSIONITIPI,ANAGRAFE TITOLARE,CONCESSIONICAUSALI CAUS_ATTUALE,ANAGRAFE IST_RICHIEDENTE,MERCATI,MERCATI_USO WHERE AUTORIZZAZIONI.IDCOMUNE = AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE AND AUTORIZZAZIONI.id = AUTORIZZAZIONI_CONCESSIONI.FK_IDAUT_ATTUALE AND CONCESSIONITIPI.TIPOCONCESSIONE = AUTORIZZAZIONI_CONCESSIONI.FK_TIPOCONCESSIONE AND TITOLARE.IDCOMUNE = AUTORIZZAZIONI.IDCOMUNE AND TITOLARE.CODICEANAGRAFE = AUTORIZZAZIONI.FK_CODICEANAGRAFE AND CAUS_ATTUALE.IDCOMUNE = AUTORIZZAZIONI.IDCOMUNE AND CAUS_ATTUALE.CODICECAUSALE = AUTORIZZAZIONI.FK_CAUSALE_ACQUISIZIONE AND ISTANZE.IDCOMUNE = AUTORIZZAZIONI.IDCOMUNE AND ISTANZE.CODICEISTANZA = AUTORIZZAZIONI.FKIDISTANZA AND IST_RICHIEDENTE.IDCOMUNE = ISTANZE.IDCOMUNE AND IST_RICHIEDENTE.CODICEANAGRAFE = ISTANZE.CODICERICHIEDENTE AND MERCATI.IDCOMUNE = AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE AND MERCATI.CODICEMERCATO = AUTORIZZAZIONI_CONCESSIONI.FK_CODICEMERCATO AND MERCATI_D.IDCOMUNE = AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE AND MERCATI_D.IDPOSTEGGIO = AUTORIZZAZIONI_CONCESSIONI.FK_IDPOSTEGGIO AND MERCATI_USO.IDCOMUNE = AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE AND MERCATI_USO.ID = AUTORIZZAZIONI_CONCESSIONI.FK_IDMERCATIUSO  UNION SELECT AUTORIZZAZIONI_SUBENTRI.IDCOMUNE,autorizzazioni_subentri.fk_causale_acquisizione as iconc_codicecausale,AUTORIZZAZIONI_SUBENTRI.DATA_CESSAZIONE as DATA_STORICO,ISTANZE.SOFTWARE,ISTANZE.CODICEISTANZA as IST_CODICEISTANZA,ISTANZE.NUMEROISTANZA as IST_NUMEROISTANZA,ISTANZE.CODICERICHIEDENTE as IST_CODICERICHIEDENTE,autorizzazioni_subentri.id as conc_id,AUTORIZZAZIONI_SUBENTRI.AUTORIZNUMERO as CONC_NUMERO,AUTORIZZAZIONI_SUBENTRI.AUTORIZDATA as CONC_DATARILASCIO,AUTORIZZAZIONI_SUBENTRI.AUTORIZDATA as DATARILASCIO,AUTORIZZAZIONI_CONCESSIONI.DATASCADENZA as CONC_DATASCADENZA,AUTORIZZAZIONI_CONCESSIONI.FK_TIPOCONCESSIONE as CONC_CODICETIPO,CONCESSIONITIPI.DESCRIZIONE as CONC_TIPO,AUTORIZZAZIONI_CONCESSIONI.STAGIONALEA as CONC_STAGIONALEA,AUTORIZZAZIONI_CONCESSIONI.STAGIONALEDA as CONC_STAGIONALEDA,0 as CONC_ATTIVA,AUTORIZZAZIONI_SUBENTRI.FK_CODICEANAGRAFE as CONC_CODICETITOLARE,CONCAT_WS('',TITOLARE.NOMINATIVO,' ',TITOLARE.NOME) as CONC_TITOLARE,titolare.codicefiscale as conc_tit_cf,TITOLARE.PARTITAIVA as CONC_TIT_PIVA,TITOLARE.TIPOANAGRAFE as CONC_TIT_TIPOANAGRAFE,AUT_COLLEGATA.AUTORIZNUMERO as AUT_NUMERO,AUT_COLLEGATA.AUTORIZDATA as AUT_DATA,AUT_COLLEGATA.AUTORIZDATA,AUT_COLLEGATA.FKIDREGISTRO as AUT_CODREGISTRO,TIPOLOGIAREGISTRI.TR_DESCRIZIONE as AUT_REGISTRO,CONCAT_WS('',IST_RICHIEDENTE.NOMINATIVO,' ',IST_RICHIEDENTE.NOME) as IST_NOMINATIVO,IST_RICHIEDENTE.TIPOANAGRAFE as IST_RIC_TIPOANAGRAFE,CONCAT_WS('',IST_AZIENDA.NOMINATIVO,' ',IST_AZIENDA.NOME) as IST_NOMINATIVOAZIENDA,IST_AZIENDA.TIPOANAGRAFE as IST_AZI_TIPOANAGRAFE,IST_RICHIEDENTE.CODICEFISCALE as IST_CODICEFISCALE,IST_RICHIEDENTE.PARTITAIVA as IST_PARTITAIVA,CAUS_ATTUALE.DESCRIZIONE as ICONC_CAUSALE,AUTORIZZAZIONI_SUBENTRI.FK_CAUSALE_CESSAZIONE as ICONC_CODICECAUSALESTORICO,CAUS_STORICO.DESCRIZIONE as ICONC_CAUSALESTORICO,autorizzazioni_concessioni.fk_codicemercato as conc_idmercato,MERCATI.DESCRIZIONE as CONC_MERCATO,MERCATI.ATTIVO as MERC_ATTIVO,AUTORIZZAZIONI_CONCESSIONI.FK_IDPOSTEGGIO as CONC_IDPOSTEGGIO,mercati_d.codiceposteggio as conc_posteggio,MERCATI_D.LARGHEZZA as CONC_POS_LARGHEZZA,MERCATI_D.LUNGHEZZA as CONC_POS_LUNGHEZZA,mercati_d.superficie as conc_pos_superficie,MERCATI_D.FKCODICETIPOSPAZIO as POST_IDTIPOSPAZIO,POSTEGGITIPOSPAZIO.TIPOSPAZIO as POST_TIPOSPAZIO,AUTORIZZAZIONI_CONCESSIONI.FK_IDMERCATIUSO as CONC_IDMERCATIUSO,MERCATI_USO.DESCRIZIONE as CONC_DESCRIZIONEUSO,MERCATI_USO.PESO as PESO_MERCATO,MERCATI_USO.FKCODICEUSO as MERC_IDUSO FROM AUTORIZZAZIONI_CONCESSIONI LEFT OUTER JOIN AUTORIZZAZIONI AUT_COLLEGATA ON AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE=AUT_COLLEGATA.IDCOMUNE  AND AUTORIZZAZIONI_CONCESSIONI.FK_IDAUT_COLLEGATA=AUT_COLLEGATA.id,AUTORIZZAZIONI_SUBENTRI LEFT OUTER JOIN TIPOLOGIAREGISTRI ON AUTORIZZAZIONI_SUBENTRI.IDCOMUNE=TIPOLOGIAREGISTRI.IDCOMUNE  AND AUTORIZZAZIONI_SUBENTRI.FKIDREGISTRO=TIPOLOGIAREGISTRI.TR_ID  LEFT OUTER JOIN CONCESSIONICAUSALI CAUS_STORICO ON AUTORIZZAZIONI_SUBENTRI.IDCOMUNE=CAUS_STORICO.IDCOMUNE,CONCESSIONITIPI,ANAGRAFE TITOLARE,CONCESSIONICAUSALI CAUS_ATTUALE,ISTANZE,ANAGRAFE IST_RICHIEDENTE,MERCATI,MERCATI_D,POSTEGGITIPOSPAZIO,MERCATI_USO,ANAGRAFE IST_AZIENDA WHERE AUTORIZZAZIONI_SUBENTRI.IDCOMUNE = AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE AND AUTORIZZAZIONI_SUBENTRI.id = AUTORIZZAZIONI_CONCESSIONI.FK_IDAUT_ATTUALE AND CONCESSIONITIPI.TIPOCONCESSIONE = AUTORIZZAZIONI_CONCESSIONI.FK_TIPOCONCESSIONE AND TITOLARE.IDCOMUNE = AUTORIZZAZIONI_SUBENTRI.IDCOMUNE AND TITOLARE.CODICEANAGRAFE = AUTORIZZAZIONI_SUBENTRI.FK_CODICEANAGRAFE AND CAUS_ATTUALE.IDCOMUNE = AUTORIZZAZIONI_SUBENTRI.IDCOMUNE AND CAUS_ATTUALE.CODICECAUSALE = AUTORIZZAZIONI_SUBENTRI.FK_CAUSALE_ACQUISIZIONE;
CREATE OR REPLACE ALGORITHM=MERGE View VW_CONCESSIONILISTA as SELECT IDCOMUNE, SOFTWARE, CONC_ID, CONC_NUMERO, CONC_DATARILASCIO, CONC_DATASCADENZA, CONC_CODICETIPO, CONC_TIPO, CONC_STAGIONALEA, CONC_STAGIONALEDA, CONC_ATTIVA, CONC_CODICETITOLARE, CONC_TITOLARE, CONC_TIT_CF, CONC_TIT_PIVA, CONC_TIT_TIPOANAGRAFE, AUT_NUMERO, AUT_DATA, AUT_CODREGISTRO, AUT_REGISTRO, IST_CODICEISTANZA, IST_NUMEROISTANZA, IST_CODICERICHIEDENTE, IST_NOMINATIVO, IST_CODICEFISCALE, IST_PARTITAIVA, IST_RIC_TIPOANAGRAFE, ICONC_CODICECAUSALE, ICONC_CAUSALE, ICONC_CODICECAUSALESTORICO, ICONC_CAUSALESTORICO, CONC_IDMERCATO, CONC_MERCATO, MERC_ATTIVO, CONC_IDPOSTEGGIO, CONC_POSTEGGIO, CONC_POS_LARGHEZZA, CONC_POS_LUNGHEZZA, CONC_POS_SUPERFICIE, POST_IDTIPOSPAZIO, POST_TIPOSPAZIO, CONC_IDMERCATIUSO, CONC_DESCRIZIONEUSO, PESO_MERCATO, MERC_IDUSO FROM  VW_ISTANZECONCESSIONILISTA;
CREATE OR REPLACE ALGORITHM=MERGE View VW_I_ATTIVITACONCESSIONI as SELECT I_ATTIVITA.ID as I_IDATTIVITA, VW_CONCESSIONILISTA.IDCOMUNE, VW_CONCESSIONILISTA.SOFTWARE, VW_CONCESSIONILISTA.CONC_ID, VW_CONCESSIONILISTA.CONC_NUMERO, VW_CONCESSIONILISTA.CONC_DATARILASCIO, VW_CONCESSIONILISTA.CONC_DATASCADENZA, VW_CONCESSIONILISTA.CONC_CODICETIPO, VW_CONCESSIONILISTA.CONC_TIPO, VW_CONCESSIONILISTA.CONC_STAGIONALEA, VW_CONCESSIONILISTA.CONC_STAGIONALEDA, VW_CONCESSIONILISTA.CONC_ATTIVA, VW_CONCESSIONILISTA.CONC_CODICETITOLARE, VW_CONCESSIONILISTA.CONC_TITOLARE, VW_CONCESSIONILISTA.CONC_TIT_CF, VW_CONCESSIONILISTA.CONC_TIT_PIVA, VW_CONCESSIONILISTA.CONC_TIT_TIPOANAGRAFE, VW_CONCESSIONILISTA.AUT_NUMERO, VW_CONCESSIONILISTA.AUT_DATA, VW_CONCESSIONILISTA.AUT_CODREGISTRO, VW_CONCESSIONILISTA.AUT_REGISTRO, VW_CONCESSIONILISTA.IST_CODICEISTANZA, VW_CONCESSIONILISTA.IST_NUMEROISTANZA, VW_CONCESSIONILISTA.IST_CODICERICHIEDENTE, VW_CONCESSIONILISTA.IST_NOMINATIVO, VW_CONCESSIONILISTA.IST_CODICEFISCALE, VW_CONCESSIONILISTA.IST_PARTITAIVA, VW_CONCESSIONILISTA.IST_RIC_TIPOANAGRAFE, VW_CONCESSIONILISTA.ICONC_CODICECAUSALE, VW_CONCESSIONILISTA.ICONC_CAUSALE, VW_CONCESSIONILISTA.ICONC_CODICECAUSALESTORICO, VW_CONCESSIONILISTA.ICONC_CAUSALESTORICO, VW_CONCESSIONILISTA.CONC_IDMERCATO, VW_CONCESSIONILISTA.CONC_MERCATO, VW_CONCESSIONILISTA.MERC_ATTIVO, VW_CONCESSIONILISTA.CONC_IDPOSTEGGIO, VW_CONCESSIONILISTA.CONC_POSTEGGIO, VW_CONCESSIONILISTA.CONC_POS_LARGHEZZA, VW_CONCESSIONILISTA.CONC_POS_LUNGHEZZA, VW_CONCESSIONILISTA.CONC_POS_SUPERFICIE, VW_CONCESSIONILISTA.POST_IDTIPOSPAZIO, VW_CONCESSIONILISTA.POST_TIPOSPAZIO, VW_CONCESSIONILISTA.CONC_IDMERCATIUSO, VW_CONCESSIONILISTA.CONC_DESCRIZIONEUSO, VW_CONCESSIONILISTA.PESO_MERCATO, VW_CONCESSIONILISTA.MERC_IDUSO FROM  I_ATTIVITA,  VW_CONCESSIONILISTA,  ISTANZE WHERE ISTANZE.IDCOMUNE = I_ATTIVITA.IDCOMUNE and ISTANZE.FK_IDI_ATTIVITA = I_ATTIVITA.ID and VW_CONCESSIONILISTA.IDCOMUNE = ISTANZE.IDCOMUNE and VW_CONCESSIONILISTA.IST_CODICEISTANZA = ISTANZE.CODICEISTANZA;
CREATE OR REPLACE ALGORITHM=MERGE View VW_ISTANZEDYN2_DATI as SELECT istanzedyn2modellit.idcomune, istanzedyn2modellit.codiceistanza, istanzedyn2modellit.fk_d2mt_id as idmodello, dyn2_modellid.posverticale, dyn2_modellid.posorizzontale, NULL as tipotesto, NULL as testo, istanzedyn2dati.indice, dyn2_campi.id as idcampo, dyn2_campi.nomecampo, istanzedyn2dati.valore FROM dyn2_campi LEFT OUTER JOIN istanzedyn2dati ON dyn2_campi.idcomune=istanzedyn2dati.idcomune  AND dyn2_campi.id=istanzedyn2dati.fk_d2c_id, dyn2_modellid, istanzedyn2modellit WHERE dyn2_campi.idcomune = dyn2_modellid.idcomune AND dyn2_campi.id = dyn2_modellid.fk_d2c_id AND dyn2_modellid.idcomune = istanzedyn2modellit.idcomune AND dyn2_modellid.fk_d2mt_id = istanzedyn2modellit.fk_d2mt_id  ORDER BY istanzedyn2modellit.idcomune, istanzedyn2modellit.codiceistanza, istanzedyn2modellit.fk_d2mt_id, dyn2_modellid.posverticale, dyn2_modellid.posorizzontale;
CREATE OR REPLACE ALGORITHM=TEMPTABLE View VW_ISTANZEDYN2_DATIMODELLO as SELECT istanzedyn2modellit.idcomune, istanzedyn2modellit.codiceistanza, istanzedyn2modellit.fk_d2mt_id as idmodello, dyn2_modellid.posverticale, dyn2_modellid.posorizzontale, dyn2_modellidtesti.fk_d2btt_id as tipotesto, dyn2_modellidtesti.testo, null as indice, null as idcampo, null as nomecampo, NULL as valore FROM dyn2_modellid LEFT OUTER JOIN dyn2_modellidtesti ON dyn2_modellid.idcomune=dyn2_modellidtesti.idcomune  AND dyn2_modellid.fk_d2mdt_id=dyn2_modellidtesti.id, istanzedyn2modellit WHERE dyn2_modellid.idcomune = istanzedyn2modellit.idcomune AND dyn2_modellid.fk_d2mt_id = istanzedyn2modellit.fk_d2mt_id UNION  select idcomune,  codiceistanza,  idmodello,  posverticale,  posorizzontale,  tipotesto,  testo,  indice,  idcampo,  nomecampo,  cast(substr(valore,1, 4000) as char charset utf8) from vw_istanzedyn2_dati;
CREATE OR REPLACE ALGORITHM=MERGE View VW_ISTANZEONERI as SELECT istanze.idcomune, istanze.software, istanzeoneri.codiceistanza, istanzeoneri.id, istanzeoneri.fkidtipocausale as causale, tipicausalioneri.co_descrizione as causaleDescrizione, istanzeoneri.data as dataregistrazione, istanzeoneri.prezzo as importo, istanzeoneri.numerorata, istanzeoneri.datascadenza as datascadenza, istanzeoneri.datapagamento as dataincasso, istanzeoneri.fkmodalitapagamento as codicemodalitaincasso, tipimodalitapagamento.mp_descrestesa as modalitaincasso, istanzeoneri.docriferimento as riferimentiincasso FROM istanzeoneri LEFT OUTER JOIN tipimodalitapagamento ON istanzeoneri.idcomune=tipimodalitapagamento.idcomune  AND istanzeoneri.fkmodalitapagamento=tipimodalitapagamento.mp_id, istanze, tipicausalioneri WHERE istanzeoneri.idcomune = istanze.idcomune AND istanzeoneri.codiceistanza = istanze.codiceistanza AND tipicausalioneri.idcomune = istanzeoneri.idcomune AND tipicausalioneri.co_id = istanzeoneri.fkidtipocausale AND istanzeoneri.flentratauscita = 1 ;
CREATE OR REPLACE ALGORITHM=MERGE View VW_ISTANZEORARI as SELECT ORARIAPERTURATESTATA.ID, ORARIAPERTURATESTATA.IDCOMUNE, ORARIAPERTURATESTATA.PERIODODA, ORARIAPERTURATESTATA.PERIODOA, ORARIAPERTURATESTATA.CODICEISTANZA, ORARIAPERTURATESTATA.FKTOID, ORARIAPERTURA_LUN.OA_DALLEORE as LUN_DALLEORE, ORARIAPERTURA_LUN.OA_ALLEORE as LUN_ALLEORE, ORARIAPERTURA_LUN.OA_DALLEOREPOM as LUN_DALLEOREPOM, ORARIAPERTURA_LUN.OA_ALLEOREPOM as LUN_ALLEOREPOM, ORARIAPERTURA_LUN.OA_FKIDORARIO as LUN_FKIDORARIO, TIPIAPERTURA_LUN.TA_DESCRIZIONE as LUN_CHIUSURA, ORARIAPERTURA_MAR.OA_DALLEORE as MAR_DALLEORE, ORARIAPERTURA_MAR.OA_ALLEORE as MAR_ALLEORE, ORARIAPERTURA_MAR.OA_DALLEOREPOM as MAR_DALLEOREPOM, ORARIAPERTURA_MAR.OA_ALLEOREPOM as MAR_ALLEOREPOM, ORARIAPERTURA_MAR.OA_FKIDORARIO as MAR_FKIDORARIO, TIPIAPERTURA_MAR.TA_DESCRIZIONE as MAR_CHIUSURA, ORARIAPERTURA_MER.OA_DALLEORE as MER_DALLEORE, ORARIAPERTURA_MER.OA_ALLEORE as MER_ALLEORE, ORARIAPERTURA_MER.OA_DALLEOREPOM as MER_DALLEOREPOM, ORARIAPERTURA_MER.OA_ALLEOREPOM as MER_ALLEOREPOM, ORARIAPERTURA_MER.OA_FKIDORARIO as MER_FKIDORARIO, TIPIAPERTURA_MER.TA_DESCRIZIONE as MER_CHIUSURA, ORARIAPERTURA_GIO.OA_DALLEORE as GIO_DALLEORE, ORARIAPERTURA_GIO.OA_ALLEORE as GIO_ALLEORE, ORARIAPERTURA_GIO.OA_DALLEOREPOM as GIO_DALLEOREPOM, ORARIAPERTURA_GIO.OA_ALLEOREPOM as GIO_ALLEOREPOM, ORARIAPERTURA_GIO.OA_FKIDORARIO as GIO_FKIDORARIO, TIPIAPERTURA_GIO.TA_DESCRIZIONE as GIO_CHIUSURA, ORARIAPERTURA_VEN.OA_DALLEORE as VEN_DALLEORE, ORARIAPERTURA_VEN.OA_ALLEORE as VEN_ALLEORE, ORARIAPERTURA_VEN.OA_DALLEOREPOM as VEN_DALLEOREPOM, ORARIAPERTURA_VEN.OA_ALLEOREPOM as VEN_ALLEOREPOM, ORARIAPERTURA_VEN.OA_FKIDORARIO as VEN_FKIDORARIO, TIPIAPERTURA_VEN.TA_DESCRIZIONE as VEN_CHIUSURA, ORARIAPERTURA_SAB.OA_DALLEORE as SAB_DALLEORE, ORARIAPERTURA_SAB.OA_ALLEORE as SAB_ALLEORE, ORARIAPERTURA_SAB.OA_DALLEOREPOM as SAB_DALLEOREPOM, ORARIAPERTURA_SAB.OA_ALLEOREPOM as SAB_ALLEOREPOM, ORARIAPERTURA_SAB.OA_FKIDORARIO as SAB_FKIDORARIO, TIPIAPERTURA_SAB.TA_DESCRIZIONE as SAB_CHIUSURA, ORARIAPERTURA_DOM.OA_DALLEORE as DOM_DALLEORE, ORARIAPERTURA_DOM.OA_ALLEORE as DOM_ALLEORE, ORARIAPERTURA_DOM.OA_DALLEOREPOM as DOM_DALLEOREPOM, ORARIAPERTURA_DOM.OA_ALLEOREPOM as DOM_ALLEOREPOM, ORARIAPERTURA_DOM.OA_FKIDORARIO as DOM_FKIDORARIO, TIPIAPERTURA_DOM.TA_DESCRIZIONE as DOM_CHIUSURA FROM ORARIAPERTURATESTATA LEFT OUTER JOIN ORARIAPERTURA ORARIAPERTURA_LUN LEFT OUTER JOIN TIPIAPERTURA TIPIAPERTURA_LUN ON ORARIAPERTURA_LUN.IDCOMUNE=TIPIAPERTURA_LUN.IDCOMUNE  AND ORARIAPERTURA_LUN.OA_FKIDORARIO=TIPIAPERTURA_LUN.TA_ID ON ORARIAPERTURATESTATA.IDCOMUNE=ORARIAPERTURA_LUN.IDCOMUNE  AND ORARIAPERTURATESTATA.ID=ORARIAPERTURA_LUN.OA_FKIDTESTATA  LEFT OUTER JOIN ORARIAPERTURA ORARIAPERTURA_MAR LEFT OUTER JOIN TIPIAPERTURA TIPIAPERTURA_MAR ON ORARIAPERTURA_MAR.IDCOMUNE=TIPIAPERTURA_MAR.IDCOMUNE  AND ORARIAPERTURA_MAR.OA_FKIDORARIO=TIPIAPERTURA_MAR.TA_ID ON ORARIAPERTURATESTATA.IDCOMUNE=ORARIAPERTURA_MAR.IDCOMUNE  AND ORARIAPERTURATESTATA.ID=ORARIAPERTURA_MAR.OA_FKIDTESTATA  LEFT OUTER JOIN ORARIAPERTURA ORARIAPERTURA_MER LEFT OUTER JOIN TIPIAPERTURA TIPIAPERTURA_MER ON ORARIAPERTURA_MER.IDCOMUNE=TIPIAPERTURA_MER.IDCOMUNE  AND ORARIAPERTURA_MER.OA_FKIDORARIO=TIPIAPERTURA_MER.TA_ID ON ORARIAPERTURATESTATA.IDCOMUNE=ORARIAPERTURA_MER.IDCOMUNE  AND ORARIAPERTURATESTATA.ID=ORARIAPERTURA_MER.OA_FKIDTESTATA  LEFT OUTER JOIN ORARIAPERTURA ORARIAPERTURA_GIO LEFT OUTER JOIN TIPIAPERTURA TIPIAPERTURA_GIO ON ORARIAPERTURA_GIO.IDCOMUNE=TIPIAPERTURA_GIO.IDCOMUNE  AND ORARIAPERTURA_GIO.OA_FKIDORARIO=TIPIAPERTURA_GIO.TA_ID ON ORARIAPERTURATESTATA.IDCOMUNE=ORARIAPERTURA_GIO.IDCOMUNE  AND ORARIAPERTURATESTATA.ID=ORARIAPERTURA_GIO.OA_FKIDTESTATA  LEFT OUTER JOIN ORARIAPERTURA ORARIAPERTURA_VEN LEFT OUTER JOIN TIPIAPERTURA TIPIAPERTURA_VEN ON ORARIAPERTURA_VEN.IDCOMUNE=TIPIAPERTURA_VEN.IDCOMUNE  AND ORARIAPERTURA_VEN.OA_FKIDORARIO=TIPIAPERTURA_VEN.TA_ID ON ORARIAPERTURATESTATA.IDCOMUNE=ORARIAPERTURA_VEN.IDCOMUNE  AND ORARIAPERTURATESTATA.ID=ORARIAPERTURA_VEN.OA_FKIDTESTATA  LEFT OUTER JOIN ORARIAPERTURA ORARIAPERTURA_SAB LEFT OUTER JOIN TIPIAPERTURA TIPIAPERTURA_SAB ON ORARIAPERTURA_SAB.IDCOMUNE=TIPIAPERTURA_SAB.IDCOMUNE  AND ORARIAPERTURA_SAB.OA_FKIDORARIO=TIPIAPERTURA_SAB.TA_ID ON ORARIAPERTURATESTATA.IDCOMUNE=ORARIAPERTURA_SAB.IDCOMUNE  AND ORARIAPERTURATESTATA.ID=ORARIAPERTURA_SAB.OA_FKIDTESTATA  LEFT OUTER JOIN ORARIAPERTURA ORARIAPERTURA_DOM LEFT OUTER JOIN TIPIAPERTURA TIPIAPERTURA_DOM ON ORARIAPERTURA_DOM.IDCOMUNE=TIPIAPERTURA_DOM.IDCOMUNE  AND ORARIAPERTURA_DOM.OA_FKIDORARIO=TIPIAPERTURA_DOM.TA_ID ON ORARIAPERTURATESTATA.IDCOMUNE=ORARIAPERTURA_DOM.IDCOMUNE  AND ORARIAPERTURATESTATA.ID=ORARIAPERTURA_DOM.OA_FKIDTESTATA WHERE ( ORARIAPERTURA_LUN.OA_FKIDGIORNO = 1 or ORARIAPERTURA_LUN.OA_FKIDGIORNO  is  NULL ) AND ( ORARIAPERTURA_MAR.OA_FKIDGIORNO = 2 or ORARIAPERTURA_MAR.OA_FKIDGIORNO  is  NULL ) AND ( ORARIAPERTURA_MER.OA_FKIDGIORNO = 3 or ORARIAPERTURA_MER.OA_FKIDGIORNO  is  NULL ) AND ( ORARIAPERTURA_GIO.OA_FKIDGIORNO = 4 or ORARIAPERTURA_GIO.OA_FKIDGIORNO  is  NULL ) AND ( ORARIAPERTURA_VEN.OA_FKIDGIORNO = 5 or ORARIAPERTURA_MAR.OA_FKIDGIORNO  is  NULL ) AND ( ORARIAPERTURA_SAB.OA_FKIDGIORNO = 6 or ORARIAPERTURA_SAB.OA_FKIDGIORNO  is  NULL ) AND ( ORARIAPERTURA_DOM.OA_FKIDGIORNO = 7 or ORARIAPERTURA_DOM.OA_FKIDGIORNO  is  NULL ) ;
CREATE OR REPLACE ALGORITHM=MERGE View VW_ISTANZEPROCEDIMENTI as SELECT ISTANZEPROCEDIMENTI.CODICEISTANZA, ISTANZEPROCEDIMENTI.CODICEINVENTARIO, INVENTARIOPROCEDIMENTI.PROCEDIMENTO, ISTANZEPROCEDIMENTI.PERPROVVEDIMENTO, ISTANZEPROCEDIMENTI.ACQUISITO, ISTANZEPROCEDIMENTI.COSTORICHIESTO, ISTANZEPROCEDIMENTI.COSTOPAGATO, ISTANZEPROCEDIMENTI.PROC_NUM, ISTANZEPROCEDIMENTI.PROT_NUM, ISTANZEPROCEDIMENTI.PROC_DEL, ISTANZEPROCEDIMENTI.PROT_DEL, ISTANZEPROCEDIMENTI.DATAATTIVAZIONE, ISTANZEPROCEDIMENTI.IDCOMUNE, ISTANZEPROCEDIMENTI.ELIMINATO, ISTANZEPROCEDIMENTI.FLAG_COMMISSIONE FROM  ISTANZEPROCEDIMENTI,  INVENTARIOPROCEDIMENTI WHERE INVENTARIOPROCEDIMENTI.IDCOMUNE = ISTANZEPROCEDIMENTI.IDCOMUNE and INVENTARIOPROCEDIMENTI.CODICEINVENTARIO = ISTANZEPROCEDIMENTI.CODICEINVENTARIO;
CREATE OR REPLACE ALGORITHM=MERGE View VW_ISTANZESOGGETTICOLLEGATI as SELECT 'S' as TIPOLOGIA,ISTANZERICHIEDENTI.CODICEISTANZA,ISTANZERICHIEDENTI.CODICERICHIEDENTE,ISTANZERICHIEDENTI.CODICEINVITATO,ISTANZERICHIEDENTI.CODICETIPOSOGGETTO,ISTANZERICHIEDENTI.IDCOMUNE,ISTANZERICHIEDENTI.CODICEANAGRAFECOLL,ifnull(ISTANZERICHIEDENTI.DESCRSOGGETTO, TIPISOGGETTO.TIPOSOGGETTO ) as DESCRSOGGETTO,ISTANZERICHIEDENTI.CODICEPROCURATORE,ISTANZE.FK_IDI_ATTIVITA FROM  ISTANZERICHIEDENTI, ISTANZE, TIPISOGGETTO WHERE TIPISOGGETTO.IDCOMUNE = ISTANZERICHIEDENTI.IDCOMUNE and TIPISOGGETTO.CODICETIPOSOGGETTO = ISTANZERICHIEDENTI.CODICETIPOSOGGETTO and ISTANZERICHIEDENTI.IDCOMUNE = ISTANZE.IDCOMUNE and ISTANZERICHIEDENTI.CODICEISTANZA = ISTANZE.CODICEISTANZA UNION SELECT 'R' as TIPOLOGIA,ISTANZE.CODICEISTANZA,ISTANZE.CODICERICHIEDENTE,NULL as CODICEINVITATO,NULL as CODICETIPOSOGGETTO,ISTANZE.IDCOMUNE,NULL as CODICEANAGRAFECOLL,ifnull(TIPISOGGETTO.TIPOSOGGETTO, 'RICHIEDENTE' ) as DESCRSOGGETTO,NULL as CODICEPROCURATORE,FK_IDI_ATTIVITA FROM ISTANZE LEFT OUTER JOIN TIPISOGGETTO ON ISTANZE.IDCOMUNE=TIPISOGGETTO.IDCOMUNE  AND ISTANZE.FKCODICESOGGETTO=TIPISOGGETTO.CODICETIPOSOGGETTO UNION SELECT 'A' as TIPOLOGIA,ISTANZE.CODICEISTANZA,ISTANZE.CODICETITOLARELEGALE,NULL as CODICEINVITATO,NULL as CODICETIPOSOGGETTO,ISTANZE.IDCOMUNE,NULL as CODICEANAGRAFECOLL,'RAGIONE SOCIALE' as DESCRSOGGETTO,NULL as CODICEPROCURATORE,FK_IDI_ATTIVITA FROM  ISTANZE WHERE NOT CODICETITOLARELEGALE  is  NULL UNION SELECT 'T' as TIPOLOGIA,ISTANZE.CODICEISTANZA,ISTANZE.CODICEPROFESSIONISTA,NULL as CODICEINVITATO,NULL as CODICETIPOSOGGETTO,ISTANZE.IDCOMUNE,NULL as CODICEANAGRAFECOLL,'PROFESSIONISTA' as DESCRSOGGETTO,NULL as CODICEPROCURATORE,FK_IDI_ATTIVITA FROM  ISTANZE WHERE NOT CODICEPROFESSIONISTA  is  NULL;
CREATE OR REPLACE ALGORITHM=MERGE View VW_LISTAPRATICHE as SELECT istanze.codicecomune, istanze.idcomune, istanze.software as software, software.descrizionelunga as descsoftware, istanze.codiceistanza as idpratica, istanze.numeroistanza as numeropratica, DATE_FORMAT(istanze.data, '%d/%m/%Y') as datapresentazione, DATE_FORMAT(istanze.data, '%Y') as annopresentazione, DATE_FORMAT(istanze.data, '%m') as mesepresentazione, istanze.numeroprotocollo, DATE_FORMAT(istanze.dataprotocollo, '%d/%m/%Y') as dataprotocollo, istanze.codiceinterventoproc as codiceintervento, vw_alberoproc.sc_descrizione as descrizioneintervento, tipiprocedure.codiceprocedura, tipiprocedure.procedura, istanze.lavori as oggetto, UPPER(istanze.lavori) as oggettou, istanze.chiusura as codstatopratica, stato as statopratica, responsabili.responsabile, responsabili.telefonolavoro as responsabile_telefono, ifnull(stradario.codviario, stradario.codicestradario) as pr_codviario, CONCAT_WS('', stradario.prefisso,' ', stradario.descrizione) as pr_indirizzo, istanzestradario.CODICECIVICO as pr_codcivico, istanze.civico as pr_civico, istanze.codicearea as codicezonizzazione, aree.denominazione as zonizzazione, anagrafe.codiceanagrafe as CodiceRichiedente, ifnull(anagrafe.codicefiscale,  '') as codicefiscale, ifnull(anagrafe.partitaiva,  '') as partitaiva, CONCAT_WS('', anagrafe.nominativo,' ', anagrafe.nome) as nominativo, anagrafe.indirizzo, anagrafe.cap, anagrafe.citta as localita, comuneresidenza.comune as citta, comuneresidenza.provincia, tipisoggetto.tiposoggetto as tiporapporto, catasto.descrizione as tipocatasto, istanzemappali.foglio, istanzemappali.particella, istanzemappali.sub, tecnico.codiceanagrafe as tec_codice, CONCAT_WS('', tecnico.nominativo,' ', tecnico.nome) as tec_nominativo, ifnull(tecnico.codicefiscale,  '') as tec_codicefiscale, ifnull(tecnico.partitaiva,  '') as tec_partitaiva, azienda.codiceanagrafe as az_codice, CONCAT_WS('', azienda.nominativo,' ', azienda.nome) as az_nominativo, ifnull(azienda.codicefiscale,  '') as az_codicefiscale, ifnull(azienda.partitaiva,  '') as az_partitaiva, istruttori.responsabile as istruttore, istruttori.telefonolavoro as istruttore_telefono, operatori.responsabile as operatore, operatori.telefonolavoro as operatore_telefono FROM istanze LEFT OUTER JOIN anagrafe tecnico ON istanze.idcomune=tecnico.idcomune  AND istanze.codiceprofessionista=tecnico.codiceanagrafe  LEFT OUTER JOIN anagrafe azienda ON istanze.idcomune=azienda.idcomune  AND istanze.codicetitolarelegale=azienda.codiceanagrafe  LEFT OUTER JOIN istanzemappali LEFT OUTER JOIN catasto ON istanzemappali.codicecatasto=catasto.codice ON istanze.idcomune=istanzemappali.idcomune  AND istanze.codiceistanza=istanzemappali.fkcodiceistanza  LEFT OUTER JOIN responsabili ON istanze.idcomune=responsabili.idcomune  AND istanze.codiceresponsabileproc=responsabili.codiceresponsabile  LEFT OUTER JOIN tipisoggetto ON istanze.idcomune=tipisoggetto.idcomune  AND istanze.fkcodicesoggetto=tipisoggetto.codicetiposoggetto  LEFT OUTER JOIN aree ON istanze.idcomune=aree.idcomune  AND istanze.codicearea=aree.codicearea  LEFT OUTER JOIN tipiprocedure ON istanze.idcomune=tipiprocedure.idcomune  AND istanze.codiceprocedura=tipiprocedure.codiceprocedura  LEFT OUTER JOIN responsabili istruttori ON istanze.idcomune=istruttori.idcomune  AND istanze.codiceistruttore=istruttori.codiceresponsabile  LEFT OUTER JOIN responsabili operatori ON istanze.idcomune=operatori.idcomune  AND istanze.codiceresponsabile=operatori.codiceresponsabile, anagrafe LEFT OUTER JOIN comuni comuneresidenza ON anagrafe.comuneresidenza=comuneresidenza.codicecomune, software, istanzestradario, stradario, vw_alberoproc, statiistanza WHERE software.codice = istanze.software AND anagrafe.idcomune = istanze.idcomune AND anagrafe.codiceanagrafe = istanze.codicerichiedente AND statiistanza.idcomune = istanze.idcomune AND statiistanza.software = istanze.software AND statiistanza.codicestato = istanze.chiusura AND istanzestradario.idcomune = istanze.idcomune AND istanzestradario.codiceistanza = istanze.codiceistanza AND istanzestradario.primario = 1 AND stradario.idcomune = istanzestradario.idcomune AND stradario.codicestradario = istanzestradario.codicestradario AND istanzemappali.primario = 1 AND vw_alberoproc.idcomune = istanze.idcomune AND vw_alberoproc.sc_id = istanze.codiceinterventoproc ;
CREATE OR REPLACE ALGORITHM=TEMPTABLE View VW_ONERIREGULUS as SELECT istanzeoneri.idcomune, istanzeoneri.fkidtipocausale, count(istanzeoneri.numerorata) as numerorate, istanzeoneri.codiceistanza, sum(istanzeoneri.prezzo) as importo, istanze.codicerichiedente as richiedente, anagrafe.codicefiscale as codifiscale, anagrafe.partitaiva as partitaiva, impresa.codicefiscale as codifiscale_impresa, impresa.partitaiva as partitaiva_impresa, tipicausalioneri.pagamentiregulus, tipicausalioneri.fkidcausalebollo, istanzeoneri.nr_documento FROM istanze LEFT OUTER JOIN anagrafe impresa ON istanze.idcomune = impresa.idcomune AND istanze.codicetitolarelegale = impresa.codiceanagrafe, istanzeoneri, anagrafe, tipicausalioneri WHERE istanzeoneri.idcomune = istanze.idcomune AND istanzeoneri.codiceistanza = istanze.codiceistanza AND istanze.idcomune = anagrafe.idcomune AND istanze.codicerichiedente = anagrafe.codiceanagrafe AND tipicausalioneri.idcomune = istanzeoneri.idcomune AND tipicausalioneri.co_id = istanzeoneri.fkidtipocausale AND tipicausalioneri.pagamentiregulus = 1  GROUP BY istanzeoneri.fkidtipocausale, istanzeoneri.codiceistanza, istanzeoneri.idcomune, istanze.codicerichiedente, anagrafe.codicefiscale, anagrafe.partitaiva, impresa.codicefiscale, impresa.partitaiva, tipicausalioneri.pagamentiregulus, tipicausalioneri.fkidcausalebollo, istanzeoneri.nr_documento;
CREATE OR REPLACE ALGORITHM=MERGE View VW_POSTEGGIMERCATOUSO as SELECT mercati.idcomune, mercati.codicemercato, mercati_uso.id as iduso, mercati_d.idposteggio FROM  mercati,  mercati_d,  mercati_uso WHERE mercati_uso.idcomune = mercati.idcomune and mercati_uso.fkcodicemercato = mercati.codicemercato and mercati.idcomune = mercati_d.idcomune and mercati.codicemercato = mercati_d.fkcodicemercato;
CREATE OR REPLACE ALGORITHM=MERGE View VW_POSTEGGICONCESSIONI as SELECT vw_posteggimercatouso.IDCOMUNE, vw_posteggimercatouso.CODICEMERCATO, vw_posteggimercatouso.IDUSO, vw_posteggimercatouso.IDPOSTEGGIO, vw_concessioniattive.codiceconcessione, vw_concessioniattive.codiceistanza, vw_concessioniattive.codiceoccupante, vw_concessioniattive.codicetitolare FROM vw_posteggimercatouso LEFT OUTER JOIN vw_concessioniattive ON vw_posteggimercatouso.idcomune=vw_concessioniattive.idcomune  AND vw_posteggimercatouso.codicemercato=vw_concessioniattive.fk_codicemercato  AND vw_posteggimercatouso.iduso=vw_concessioniattive.fk_idmercatiuso  AND vw_posteggimercatouso.idposteggio=vw_concessioniattive.fk_idposteggio;
CREATE OR REPLACE ALGORITHM=MERGE View VW_POSTEGGICONCESSIONIPRESENZE as SELECT VW_POSTEGGICONCESSIONI.CODICEMERCATO, VW_POSTEGGICONCESSIONI.IDUSO, VW_POSTEGGICONCESSIONI.IDPOSTEGGIO, VW_POSTEGGICONCESSIONI.CODICECONCESSIONE, VW_POSTEGGICONCESSIONI.CODICEISTANZA, VW_POSTEGGICONCESSIONI.CODICEOCCUPANTE, VW_POSTEGGICONCESSIONI.CODICETITOLARE, MERCATIPRESENZE_D.* FROM  VW_POSTEGGICONCESSIONI LEFT OUTER JOIN MERCATIPRESENZE_D ON VW_POSTEGGICONCESSIONI.IDCOMUNE = MERCATIPRESENZE_D.IDCOMUNE AND VW_POSTEGGICONCESSIONI.IDPOSTEGGIO = MERCATIPRESENZE_D.FKIDPOSTEGGIO;
CREATE OR REPLACE ALGORITHM=MERGE View VW_PROCEDIMENTI_STP as select  INVENTARIOPROCEDIMENTI.IDCOMUNE, IFNULL(inventarioprocedimentipeople.cod_proc_people, cast(inventarioprocedimenti.codiceinventario as char charset utf8)) AS codiceSTP, inventarioprocedimenti.codiceinventario FROM INVENTARIOPROCEDIMENTI LEFT JOIN inventarioprocedimentipeople   ON INVENTARIOPROCEDIMENTI.IDCOMUNE=INVENTARIOPROCEDIMENTIPEOPLE.IDCOMUNE   AND INVENTARIOPROCEDIMENTI.CODICEINVENTARIO=INVENTARIOPROCEDIMENTIPEOPLE.CODICEINVENTARIO;
CREATE OR REPLACE ALGORITHM=MERGE View VW_ALBEROPROC_STP as SELECT VW_procedimenti_STP.IDCOMUNE, alberoproc.SOFTWARE, VW_procedimenti_STP.CODICESTP, VW_procedimenti_STP.CODICEINVENTARIO, alberoproc_endo.fkscid as SC_id FROM  alberoproc,  VW_procedimenti_STP,  alberoproc_endo WHERE alberoproc_endo.idcomune = vw_procedimenti_stp.idcomune and alberoproc_endo.codiceinventario = vw_procedimenti_stp.codiceinventario and alberoproc.idcomune = alberoproc_endo.idcomune and alberoproc.sc_id = alberoproc_endo.fkscid;
CREATE OR REPLACE ALGORITHM=MERGE View VW_PROTOCOLLO_RESPFLUSSI as SELECT IDCOMUNE, case mr_fkidmodalita when 1 then 'A' when 2 then 'P' when 3 then 'I' end as CODICEFLUSSO, mr_fkidresponsabile as CODICERESPONSABILE FROM  prot_modalitaresponsabili;
CREATE OR REPLACE ALGORITHM=MERGE View VW_PROTOCOLLO_TIPIDOCUMENTO as SELECT IDCOMUNE, cast(`prot_tipologiaprotocollo`.`TP_ID` as char charset utf8) as CODICE, TP_DESCRIZIONE as DESCRIZIONE FROM  PROT_TIPOLOGIAPROTOCOLLO UNION select IDCOMUNE,  CODICE,  DESCRIZIONE from PROTOCOLLO_TIPIDOCUMENTO;
CREATE OR REPLACE ALGORITHM=MERGE View VW_PROVINCE as SELECT SIGLAPROVINCIA, PROVINCIA FROM  COMUNI GROUP BY SIGLAPROVINCIA, PROVINCIA;
CREATE OR REPLACE ALGORITHM=TEMPTABLE View VW_REGISTRAZIONIDEBITI as SELECT id_REGISTRAZIONE, IDCOMUNE, SOFTWARE, count(rata_non_pagata) as rate_non_pagate, SUM(importo_rata) as importo_rate, SUM(incassato_rata) as incassato_rate, (SUM(importo_rata) - ifnull(SUM(incassato_rata), 0)) as DA_INCASSARE FROM VW_A_REGISTRAZIONI_DEBITI GROUP BY id_registrazione, SOFTWARE, IDCOMUNE;
CREATE OR REPLACE ALGORITHM=MERGE View VW_REGISTRAZIONISALDO as SELECT importi_non_ridotti.id as id, importi_non_ridotti.idcomune as idcomune, importi_non_ridotti.importo_registrazione as importo_registrazione, importi_non_ridotti.incassato + importi_ridotti.incassato as incassato, importi_ridotti.incassato as incassato_ridotto, (saldo_ridotti.saldo - importi_ridotti.incassato) as saldo_ridotto, importi_non_ridotti.incassato as incassato_non_ridotto, importi_non_ridotti.saldo as saldo_non_ridotto, case SIGN(importi_non_ridotti.importo_registrazione) when 1 then  case importi_ridotti.incassato when 0 then  ((importi_non_ridotti.saldo - ifnull(saldo_ridotti.saldo, 0)) - (importi_non_ridotti.incassato-(importi_non_ridotti.incassato + importi_ridotti.incassato)))  ELSE  ( importi_non_ridotti.importo_registrazione -(importi_non_ridotti.incassato + ifnull(saldo_ridotti.saldo, 0)))  end  ELSE 0 end as saldo FROM vw_a_importi_non_ridotti importi_non_ridotti LEFT OUTER JOIN vw_a_importi_ridotti importi_ridotti ON importi_non_ridotti.idcomune=importi_ridotti.idcomune  AND importi_non_ridotti.id=importi_ridotti.id LEFT OUTER JOIN vw_a_saldo_ridotti saldo_ridotti ON importi_non_ridotti.idcomune=saldo_ridotti.idcomune  AND importi_non_ridotti.id=saldo_ridotti.id;
CREATE OR REPLACE ALGORITHM=MERGE View VW_SCADENZARIO as SELECT BATCH_SCADENZARIO.IDCOMUNE as IDCOMUNE, BATCH_SCADENZARIO.ID as CODICESCADENZA, BATCH_SCADENZARIO.SOFTWARE as software, BATCH_SCADENZARIO.CODICEISTANZA as codiceistanza, ISTANZE.NUMEROPROTOCOLLO as numeroprotocollo, ISTANZE.DATAPROTOCOLLO as dataprotocollo, ISTANZE.NUMEROISTANZA as NUMEROISTANZA, ISTANZE.CHIUSURA as CODSTATOISTANZA, STATIISTANZA.STATO as DESCRSTATOISTANZA, BATCH_SCADENZARIO.CODICEMOVIMENTO as CODMOVIMENTO, BATCH_SCADENZARIO.DESCRMOVIMENTO as DESCRMOVIMENTO, DATE_FORMAT(MOVIMENTI.DATA, '%d/%m/%Y') as DATAMOVIMENTO, BATCH_SCADENZARIO.TIPOMOVIMENTODAFARE as CODMOVIMENTODAFARE, BATCH_SCADENZARIO.DESCRMOVIMENTODAFARE as DESCRMOVIMENTODAFARE, DATE_FORMAT(BATCH_SCADENZARIO.DATASCADENZA, '%d/%m/%Y') as DATASCADENZASTR, BATCH_SCADENZARIO.codiceinventario as codiceinventario, BATCH_SCADENZARIO.CODICEAMMINISTRAZIONE as CODICEAMMINISTRAZIONE, RESPONSABILI.RESPONSABILE as RESPONSABILE, INVENTARIOPROCEDIMENTI.PROCEDIMENTO as PROCEDIMENTO, TIPIPROCEDURE.PROCEDURA as PROCEDURA, SOFTWARE.DESCRIZIONE as MODULOSOFTWARE, amministrazioni.AMMINISTRAZIONE as AMM_amministrazione, AMMINISTRAZIONI.PARTITAIVA as AMM_PARTITAIVA, AMMINISTRAZIONI.PASSWORD as AMM_PASSWORD, CONCAT_WS('', ANAGRAFE.NOMINATIVO,' ', ANAGRAFE.NOME) as RIC_NOMINATIVO, ifnull(ANAGRAFE.CODICEFISCALE, '') as RIC_CODICEFISCALE, ifnull(ANAGRAFE.PARTITAIVA, '') as RIC_PARTITAIVA, ANAGRAFE.INDIRIZZO as RIC_INDIRIZZO, ANAGRAFE.CAP as RIC_CAP, ANAGRAFE.CITTA as RIC_LOCALITA, COMUNERESIDENZA.COMUNE as RIC_CITTA, COMUNERESIDENZA.PROVINCIA as RIC_PROVINCIA, ANAGRAFE.PASSWORD as RIC_PASSWORD, CONCAT_WS('', TECNICO.NOMINATIVO,' ', TECNICO.NOME) as TEC_NOMINATIVO, ifnull(TECNICO.CODICEFISCALE, '') as TEC_CODICEFISCALE, ifnull(TECNICO.PARTITAIVA, '') as TEC_PARTITAIVA, TECNICO.PASSWORD as TEC_PASSWORD, CONCAT_WS('', AZIENDA.NOMINATIVO,' ', AZIENDA.NOME) as AZ_NOMINATIVO, ifnull(AZIENDA.CODICEFISCALE, '') as AZ_CODICEFISCALE, ifnull(AZIENDA.PARTITAIVA, '') as AZ_PARTITAIVA, AZIENDA.PASSWORD as AZ_PASSWORD, TIPIMOVIMENTO.FK_FO_SOGGETTIESTERNI FROM ANAGRAFE LEFT OUTER JOIN COMUNI COMUNERESIDENZA ON ANAGRAFE.COMUNERESIDENZA=COMUNERESIDENZA.CODICECOMUNE, ISTANZE LEFT OUTER JOIN ANAGRAFE TECNICO ON ISTANZE.IDCOMUNE=TECNICO.IDCOMUNE  AND ISTANZE.CODICEPROFESSIONISTA=TECNICO.CODICEANAGRAFE  LEFT OUTER JOIN ANAGRAFE AZIENDA ON ISTANZE.IDCOMUNE=AZIENDA.IDCOMUNE  AND ISTANZE.CODICETITOLARELEGALE=AZIENDA.CODICEANAGRAFE, BATCH_SCADENZARIO, RESPONSABILI, INVENTARIOPROCEDIMENTI, MOVIMENTI, TIPIPROCEDURE, SOFTWARE, STATIISTANZA, AMMINISTRAZIONI, TIPIMOVIMENTO WHERE ISTANZE.IDCOMUNE = BATCH_SCADENZARIO.IDCOMUNE AND ISTANZE.CODICEISTANZA = BATCH_SCADENZARIO.CODICEISTANZA AND RESPONSABILI.IDCOMUNE = ISTANZE.IDCOMUNE AND RESPONSABILI.CODICERESPONSABILE = ISTANZE.CODICERESPONSABILE AND INVENTARIOPROCEDIMENTI.IDCOMUNE = BATCH_SCADENZARIO.IDCOMUNE AND INVENTARIOPROCEDIMENTI.CODICEINVENTARIO = BATCH_SCADENZARIO.CODICEINVENTARIO AND MOVIMENTI.IDCOMUNE = BATCH_SCADENZARIO.IDCOMUNE AND MOVIMENTI.CODICEMOVIMENTO = BATCH_SCADENZARIO.CODICEMOVIMENTO AND TIPIMOVIMENTO.IDCOMUNE = BATCH_SCADENZARIO.IDCOMUNE AND TIPIMOVIMENTO.TIPOMOVIMENTO = BATCH_SCADENZARIO.TIPOMOVIMENTODAFARE AND TIPIPROCEDURE.IDCOMUNE = ISTANZE.IDCOMUNE AND TIPIPROCEDURE.CODICEPROCEDURA = ISTANZE.CODICEPROCEDURA AND SOFTWARE.CODICE = BATCH_SCADENZARIO.SOFTWARE AND ANAGRAFE.IDCOMUNE = ISTANZE.IDCOMUNE AND ANAGRAFE.CODICEANAGRAFE = ISTANZE.CODICERICHIEDENTE AND STATIISTANZA.IDCOMUNE = ISTANZE.IDCOMUNE AND STATIISTANZA.SOFTWARE = ISTANZE.SOFTWARE AND STATIISTANZA.CODICESTATO = ISTANZE.CHIUSURA AND AMMINISTRAZIONI.IDCOMUNE = BATCH_SCADENZARIO.IDCOMUNE AND AMMINISTRAZIONI.CODICEAMMINISTRAZIONE = BATCH_SCADENZARIO.CODICEAMMINISTRAZIONE ;
CREATE OR REPLACE ALGORITHM=MERGE View VW_STATISTICHEISTANZE as SELECT DISTINCT ISTANZE.IDCOMUNE as f_idcomune, ISTANZE.SOFTWARE as f_software, ISTANZE.DATA as f_data, ifnull(ISTANZE.codiceResponsabile, -1) as f_responsabile, ifnull(ISTANZE.codiceprofessionista, -1) as f_professionista, ifnull(ISTANZE.CODICEINTERVENTOPROC, ISTANZE.CODICEINTERVENTO) as f_codiceintervento, ifnull(ISTANZE.METRIQUADRATI, 0) as f_metriquadrati, ifnull(ISTANZE.CODICEPROCEDURA, -1) as f_procedura, ifnull(ISTANZEATTIVITA.CodiceAttivita, ' ') as f_dettaglioinformazioni, ifnull(SETTORI.CodiceSettore, -1) as f_tipoinformazioni, ifnull(ISTANZEAREE.CODICEAREA, -1) as f_zonizzazione, ifnull(AUTORIZZAZIONI.FKIDREGISTRO, -1) as f_registro, ifnull(ISTANZE.CHIUSURA, ' ') as f_stato, ISTANZE.CODICEISTANZA, ISTANZE.CODICERESPONSABILE, ISTANZE.CODICERICHIEDENTE, ISTANZE.CODICEPROFESSIONISTA, ISTANZE.DATA, ISTANZE.NUMEROPROTOCOLLO, ISTANZE.DATAPROTOCOLLO, ISTANZE.CODICEINTERVENTO, ISTANZE.LAVORI, ISTANZE.CODICEPROCEDURA, ISTANZE.CODICEAREA, ISTANZE.CODICELOTTO, ISTANZE.PASSWORD, ISTANZE.ATTIVA, ISTANZE.FOGLIO, ISTANZE.PARTICELLA, ISTANZE.SUB, ISTANZE.CODICESETTORE, ISTANZE.VARIANTEPR, ISTANZE.CODICEIMPIANTO, ISTANZE.CODICEATTIVITA, ISTANZE.FLAGVIA, ISTANZE.CHIUSURA, ISTANZE.PROGREGAUT, ISTANZE.LAVORIESTESA, ISTANZE.CODICEARCHIVIO, ISTANZE.CODICESTRADARIO, ISTANZE.CIVICO, ISTANZE.AUTORIZNUMERO, ISTANZE.AUTORIZDATA, ISTANZE.AUTORIZDATAREGISTR, ISTANZE.AUTORIZRESPONSABILE, ISTANZE.TIPOMOVAVVIO, ISTANZE.TIPOARCHIVIO, ISTANZE.CODICECOMUNE, ISTANZE.SOFTWARE, ISTANZE.IDMODELLO, ISTANZE.CODICEINTERVENTOPROC, ISTANZE.NUMEROISTANZA, ISTANZE.IDCOMUNE, ISTANZE.SETITOLARELEGALE, ISTANZE.FKIDTIPOLOGIAISTANZA, ISTANZE.CODICETITOLARELEGALE, ISTANZE.FKTOID, ISTANZE.METRIQUADRATI, ISTANZE.GIORNOCHIUSURA, ISTANZE.CODISTANZACOLLEGATA, ISTANZE.AZIONE, ISTANZE.FKIDREGISTRO, ISTANZE.NOMEATTIVITA, ISTANZE.FKIDFORMATO, ISTANZE.POSIZIONEARCHIVIO, ISTANZE.BASE, ISTANZE.ALTEZZA, ISTANZE.FACCE, ISTANZE.FKIDPROTOCOLLO, ISTANZE.FKCODICESOGGETTO, ISTANZE.CODICEISTRUTTORE, ISTANZE.CODICERESPONSABILEPROC, ISTANZE.CODICEAREA2, ISTANZE.FK_IDI_ATTIVITA, ISTANZE.DATAVALIDITA, ISTANZE.I_ATTIVITAORDINE, ISTANZE.CREATO_DA_STC, ISTANZE.DESCRSOGGETTO FROM ISTANZE LEFT OUTER JOIN ISTANZEATTIVITA LEFT OUTER JOIN ATTIVITA LEFT OUTER JOIN SETTORI ON ATTIVITA.IDCOMUNE=SETTORI.IDCOMUNE  AND ATTIVITA.CODICESETTORE=SETTORI.CODICESETTORE ON ISTANZEATTIVITA.IDCOMUNE=ATTIVITA.IDCOMUNE  AND ISTANZEATTIVITA.CODICEATTIVITA=ATTIVITA.CODICEISTAT ON ISTANZE.IDCOMUNE=ISTANZEATTIVITA.IDCOMUNE  AND ISTANZE.CODICEISTANZA=ISTANZEATTIVITA.CODICEISTANZA  LEFT OUTER JOIN ISTANZEAREE ON ISTANZE.IDCOMUNE=ISTANZEAREE.IDCOMUNE  AND ISTANZE.CODICEISTANZA=ISTANZEAREE.CODICEISTANZA  LEFT OUTER JOIN AUTORIZZAZIONI ON ISTANZE.IDCOMUNE=AUTORIZZAZIONI.IDCOMUNE  AND ISTANZE.CODICEISTANZA=AUTORIZZAZIONI.FKIDISTANZA;
CREATE OR REPLACE ALGORITHM=MERGE View VW_STRADARIO as SELECT CODICESTRADARIO, TRIM( CONCAT_WS('', PREFISSO,' ', DESCRIZIONE))  as INDIRIZZO, PREFISSO, DESCRIZIONE,CAP, LOCFRAZ, FKIDZONA, CODICECOMUNE, IDCOMUNE, CS_DATE, CODVIARIO, DATAVALIDITA FROM  STRADARIO;
CREATE OR REPLACE ALGORITHM=TEMPTABLE View VW_TMPSTAT_MAX_COLLEGAMENTO as SELECT SESSIONID, IDPRATICA, CODICEISTANZA, MAX(ORDINECOLLEGAMENTO) as ORDINECOLLEGAMENTO FROM  TMP_STAT_02 GROUP BY SESSIONID, IDPRATICA, CODICEISTANZA;
CREATE OR REPLACE ALGORITHM=TEMPTABLE View VW_ISTANZECOLLEGATE (IDCOMUNE,PROGRESSIVO,CODICEISTANZA,ORDINE) AS SELECT IDCOMUNE,PROGRESSIVO,CODICEISTANZA,ORDINE FROM ISTANZECOLLEGATE GROUP BY IDCOMUNE,PROGRESSIVO,CODICEISTANZA,ORDINE;


CREATE OR REPLACE ALGORITHM=MERGE VIEW VW_LISTAPRATICHE AS select istanze.CODICECOMUNE AS codicecomune,istanze.IDCOMUNE AS idcomune,istanze.SOFTWARE AS software,software.DESCRIZIONELUNGA AS descsoftware,istanze.CODICEISTANZA AS idpratica,istanze.NUMEROISTANZA AS numeropratica,date_format(istanze.DATA,_utf8'%d/%m/%Y') AS datapresentazione,date_format(istanze.DATA,_utf8'%Y') AS annopresentazione,date_format(istanze.DATA,_utf8'%m') AS mesepresentazione,istanze.NUMEROPROTOCOLLO AS numeroprotocollo,date_format(istanze.DATAPROTOCOLLO,_utf8'%d/%m/%Y') AS dataprotocollo,istanze.CODICEINTERVENTOPROC AS codiceintervento,vw_alberoproc.SC_DESCRIZIONE AS descrizioneintervento,tipiprocedure.CODICEPROCEDURA AS codiceprocedura,tipiprocedure.PROCEDURA AS procedura,istanze.LAVORI AS oggetto,ucase(istanze.LAVORI) AS oggettou,istanze.CHIUSURA AS codstatopratica,statiistanza.STATO AS statopratica,responsabili.RESPONSABILE AS responsabile,responsabili.TELEFONOLAVORO AS responsabile_telefono,ifnull(stradario.CODVIARIO,stradario.CODICESTRADARIO) AS pr_codviario,concat_ws(_utf8'',stradario.PREFISSO,_utf8' ',stradario.DESCRIZIONE) AS pr_indirizzo,istanzestradario.CODICECIVICO AS pr_codcivico,istanze.CIVICO AS pr_civico,istanze.CODICEAREA AS codicezonizzazione,aree.DENOMINAZIONE AS zonizzazione,anagrafe.CODICEANAGRAFE AS CodiceRichiedente,ifnull(anagrafe.CODICEFISCALE,_utf8'') AS codicefiscale,ifnull(anagrafe.PARTITAIVA,_utf8'') AS partitaiva,concat_ws(_utf8'',anagrafe.NOMINATIVO,_utf8' ',anagrafe.NOME) AS nominativo,anagrafe.INDIRIZZO AS indirizzo,anagrafe.CAP AS cap,anagrafe.CITTA AS localita,comuneresidenza.COMUNE AS citta,comuneresidenza.PROVINCIA AS provincia,tipisoggetto.TIPOSOGGETTO AS tiporapporto,catasto.DESCRIZIONE AS tipocatasto,istanzemappali.FOGLIO AS foglio,istanzemappali.PARTICELLA AS particella,istanzemappali.SUB AS sub,tecnico.CODICEANAGRAFE AS tec_codice,concat_ws(_utf8'',tecnico.NOMINATIVO,_utf8' ',tecnico.NOME) AS tec_nominativo,ifnull(tecnico.CODICEFISCALE,_utf8'') AS tec_codicefiscale,ifnull(tecnico.PARTITAIVA,_utf8'') AS tec_partitaiva,azienda.CODICEANAGRAFE AS az_codice,concat_ws(_utf8'',azienda.NOMINATIVO,_utf8' ',azienda.NOME) AS az_nominativo,ifnull(azienda.CODICEFISCALE,_utf8'') AS az_codicefiscale,ifnull(azienda.PARTITAIVA,_utf8'') AS az_partitaiva,istruttori.RESPONSABILE AS istruttore,istruttori.TELEFONOLAVORO AS istruttore_telefono,operatori.RESPONSABILE AS operatore,operatori.TELEFONOLAVORO AS operatore_telefono from 
(((((((((((((((istanze left join anagrafe tecnico on(((istanze.IDCOMUNE = tecnico.IDCOMUNE) and (istanze.CODICEPROFESSIONISTA = tecnico.CODICEANAGRAFE)))) left join anagrafe azienda on(((istanze.IDCOMUNE = azienda.IDCOMUNE) and (istanze.CODICETITOLARELEGALE = azienda.CODICEANAGRAFE)))) left join (istanzemappali left join catasto on((istanzemappali.CODICECATASTO = catasto.CODICE))) on(((istanze.IDCOMUNE = istanzemappali.IDCOMUNE) and (istanze.CODICEISTANZA = istanzemappali.FKCODICEISTANZA)))) left join responsabili on(((istanze.IDCOMUNE = responsabili.IDCOMUNE) and (istanze.CODICERESPONSABILEPROC = responsabili.CODICERESPONSABILE)))) left join tipisoggetto on(((istanze.IDCOMUNE = tipisoggetto.IDCOMUNE) and (istanze.FKCODICESOGGETTO = tipisoggetto.CODICETIPOSOGGETTO)))) left join aree on(((istanze.IDCOMUNE = aree.IDCOMUNE) and (istanze.CODICEAREA = aree.CODICEAREA)))) left join tipiprocedure on(((istanze.IDCOMUNE = tipiprocedure.IDCOMUNE) and (istanze.CODICEPROCEDURA = tipiprocedure.CODICEPROCEDURA)))) left join responsabili istruttori on(((istanze.IDCOMUNE = istruttori.IDCOMUNE) and (istanze.CODICEISTRUTTORE = istruttori.CODICERESPONSABILE)))) left join responsabili operatori on(((istanze.IDCOMUNE = operatori.IDCOMUNE) and (istanze.CODICERESPONSABILE = operatori.CODICERESPONSABILE)))) join (anagrafe left join comuni comuneresidenza on((anagrafe.COMUNERESIDENZA = comuneresidenza.CODICECOMUNE)))) join software) join istanzestradario) join stradario) join vw_alberoproc) join statiistanza) WHERE 
((software.CODICE = istanze.SOFTWARE) and (anagrafe.IDCOMUNE = istanze.IDCOMUNE) and (anagrafe.CODICEANAGRAFE = istanze.CODICERICHIEDENTE) and (statiistanza.IDCOMUNE = istanze.IDCOMUNE) and (statiistanza.SOFTWARE = istanze.SOFTWARE) and (statiistanza.CODICESTATO = istanze.CHIUSURA) and (istanzestradario.IDCOMUNE = istanze.IDCOMUNE) and (istanzestradario.CODICEISTANZA = istanze.CODICEISTANZA) and (istanzestradario.PRIMARIO = 1) and (stradario.IDCOMUNE = istanzestradario.IDCOMUNE) and (stradario.CODICESTRADARIO = istanzestradario.CODICESTRADARIO) and (istanzemappali.PRIMARIO = 1) and (vw_alberoproc.IDCOMUNE = istanze.IDCOMUNE) and (vw_alberoproc.SC_ID = istanze.CODICEINTERVENTOPROC));


CREATE OR REPLACE ALGORITHM=MERGE View VW_DOCUMENTIISTANZA as SELECT 'DOCUMENTI' as TIPOLOGIA,
DOCUMENTIISTANZA.DOCUMENTO as DESCRIZIONE,
DOCUMENTIISTANZA.DATA,
DOCUMENTIISTANZA.CODICEOGGETTO,
DOCUMENTIISTANZA.STC_IDALLEGATO,
DOCUMENTIISTANZA.STC_IDDOCUMENTO,
DOCUMENTIISTANZA.CODICEISTANZA,
DOCUMENTIISTANZA.IDCOMUNE FROM  DOCUMENTIISTANZA UNION  SELECT 'MOVIMENTI' AS TIPOLOGIA,
 MOVIMENTIALLEGATI.DESCRIZIONE,
 MOVIMENTI.DATA,
 MOVIMENTIALLEGATI.CODICEOGGETTO,
 MOVIMENTIALLEGATI.STC_IDALLEGATO,
 MOVIMENTIALLEGATI.STC_IDDOCUMENTO,
 MOVIMENTI.CODICEISTANZA,
 MOVIMENTI.IDCOMUNE FROM MOVIMENTI,
 MOVIMENTIALLEGATI WHERE MOVIMENTIALLEGATI.IDCOMUNE = MOVIMENTI.IDCOMUNE AND MOVIMENTIALLEGATI.CODICEMOVIMENTO = MOVIMENTI.CODICEMOVIMENTO  UNION  SELECT 'ENDOPROCEDIMENTI' AS TIPOLOGIA,
 ISTANZEALLEGATI.ALLEGATOEXTRA AS DESCRIZIONE,
 ISTANZEPROCEDIMENTI.DATAATTIVAZIONE AS DATA,
 ISTANZEALLEGATI.CODICEOGGETTO,
 ISTANZEALLEGATI.STC_IDALLEGATO,
 ISTANZEALLEGATI.STC_IDDOCUMENTO,
 ISTANZEALLEGATI.CODICEISTANZA,
 ISTANZEALLEGATI.IDCOMUNE FROM INVENTARIOPROCEDIMENTI,
 ISTANZEALLEGATI,
 ISTANZEPROCEDIMENTI WHERE INVENTARIOPROCEDIMENTI.IDCOMUNE = ISTANZEPROCEDIMENTI.IDCOMUNE AND INVENTARIOPROCEDIMENTI.CODICEINVENTARIO = ISTANZEPROCEDIMENTI.CODICEINVENTARIO AND ISTANZEPROCEDIMENTI.IDCOMUNE = ISTANZEALLEGATI.IDCOMUNE AND ISTANZEPROCEDIMENTI.CODICEINVENTARIO = ISTANZEALLEGATI.CODICEINVENTARIO AND ISTANZEPROCEDIMENTI.CODICEISTANZA = ISTANZEALLEGATI.CODICEISTANZA ;

CREATE OR REPLACE ALGORITHM=TEMPTABLE VIEW VW_ISTANZECONCESSIONILISTA AS SELECT AUTORIZZAZIONI.IDCOMUNE,AUTORIZZAZIONI.FK_CAUSALE_ACQUISIZIONE AS ICONC_CODICECAUSALE,AUTORIZZAZIONI.DATA_CESSAZIONE AS DATA_STORICO,ISTANZE.SOFTWARE,ISTANZE.CODICEISTANZA AS IST_CODICEISTANZA,ISTANZE.NUMEROISTANZA AS IST_NUMEROISTANZA,ISTANZE.CODICERICHIEDENTE AS IST_CODICERICHIEDENTE,AUTORIZZAZIONI.ID AS CONC_ID,AUTORIZZAZIONI.AUTORIZNUMERO AS CONC_NUMERO,AUTORIZZAZIONI.AUTORIZDATA AS CONC_DATARILASCIO,AUTORIZZAZIONI.AUTORIZDATA AS DATARILASCIO,AUTORIZZAZIONI_CONCESSIONI.DATASCADENZA AS CONC_DATASCADENZA,AUTORIZZAZIONI_CONCESSIONI.FK_TIPOCONCESSIONE AS CONC_CODICETIPO,CONCESSIONITIPI.DESCRIZIONE AS CONC_TIPO,AUTORIZZAZIONI_CONCESSIONI.STAGIONALEA AS CONC_STAGIONALEA,AUTORIZZAZIONI_CONCESSIONI.STAGIONALEDA AS CONC_STAGIONALEDA,AUTORIZZAZIONI.FLAG_ATTIVA AS CONC_ATTIVA,AUTORIZZAZIONI.FK_CODICEANAGRAFE AS CONC_CODICETITOLARE,CONCAT_WS('',TITOLARE.NOMINATIVO,' ',TITOLARE.NOME) AS CONC_TITOLARE,TITOLARE.CODICEFISCALE AS CONC_TIT_CF,TITOLARE.PARTITAIVA AS CONC_TIT_PIVA,TITOLARE.TIPOANAGRAFE AS CONC_TIT_TIPOANAGRAFE,AUT_COLLEGATA.AUTORIZNUMERO AS AUT_NUMERO,AUT_COLLEGATA.AUTORIZDATA AS AUT_DATA,AUT_COLLEGATA.AUTORIZDATA,AUT_COLLEGATA.FKIDREGISTRO AS AUT_CODREGISTRO,TIPOLOGIAREGISTRI.TR_DESCRIZIONE AS AUT_REGISTRO,CONCAT_WS('',IST_RICHIEDENTE.NOMINATIVO,' ',IST_RICHIEDENTE.NOME) AS IST_NOMINATIVO,IST_RICHIEDENTE.TIPOANAGRAFE AS IST_RIC_TIPOANAGRAFE,CONCAT_WS('',IST_AZIENDA.NOMINATIVO,' ',IST_AZIENDA.NOME) AS IST_NOMINATIVOAZIENDA,IST_AZIENDA.TIPOANAGRAFE AS IST_AZI_TIPOANAGRAFE,IST_RICHIEDENTE.CODICEFISCALE AS IST_CODICEFISCALE,IST_RICHIEDENTE.PARTITAIVA AS IST_PARTITAIVA,CAUS_ATTUALE.DESCRIZIONE AS ICONC_CAUSALE,AUTORIZZAZIONI.FK_CAUSALE_CESSAZIONE AS ICONC_CODICECAUSALESTORICO,CAUS_STORICO.DESCRIZIONE AS ICONC_CAUSALESTORICO,AUTORIZZAZIONI_CONCESSIONI.FK_CODICEMERCATO AS CONC_IDMERCATO,MERCATI.DESCRIZIONE AS CONC_MERCATO,MERCATI.ATTIVO AS MERC_ATTIVO,AUTORIZZAZIONI_CONCESSIONI.FK_IDPOSTEGGIO AS CONC_IDPOSTEGGIO,MERCATI_D.CODICEPOSTEGGIO AS CONC_POSTEGGIO,MERCATI_D.LARGHEZZA AS CONC_POS_LARGHEZZA,MERCATI_D.LUNGHEZZA AS CONC_POS_LUNGHEZZA,MERCATI_D.SUPERFICIE AS CONC_POS_SUPERFICIE,MERCATI_D.FKCODICETIPOSPAZIO AS POST_IDTIPOSPAZIO,POSTEGGITIPOSPAZIO.TIPOSPAZIO AS POST_TIPOSPAZIO,AUTORIZZAZIONI_CONCESSIONI.FK_IDMERCATIUSO AS CONC_IDMERCATIUSO,MERCATI_USO.DESCRIZIONE AS CONC_DESCRIZIONEUSO,MERCATI_USO.PESO AS PESO_MERCATO,MERCATI_USO.FKCODICEUSO AS MERC_IDUSO, MERCATI_D.FKCODICESTRADARIO AS CONC_POS_CODICESTRADARIO FROM AUTORIZZAZIONI_CONCESSIONI LEFT OUTER JOIN AUTORIZZAZIONI AUT_COLLEGATA ON AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE=AUT_COLLEGATA.IDCOMUNE  AND AUTORIZZAZIONI_CONCESSIONI.FK_IDAUT_COLLEGATA=AUT_COLLEGATA.ID,AUTORIZZAZIONI LEFT OUTER JOIN TIPOLOGIAREGISTRI ON AUTORIZZAZIONI.IDCOMUNE=TIPOLOGIAREGISTRI.IDCOMUNE  AND AUTORIZZAZIONI.FKIDREGISTRO=TIPOLOGIAREGISTRI.TR_ID  LEFT OUTER JOIN CONCESSIONICAUSALI CAUS_STORICO ON AUTORIZZAZIONI.IDCOMUNE=CAUS_STORICO.IDCOMUNE  AND AUTORIZZAZIONI.FK_CAUSALE_CESSAZIONE=CAUS_STORICO.CODICECAUSALE,MERCATI_D LEFT OUTER JOIN POSTEGGITIPOSPAZIO ON MERCATI_D.IDCOMUNE=POSTEGGITIPOSPAZIO.IDCOMUNE AND MERCATI_D.FKCODICETIPOSPAZIO=POSTEGGITIPOSPAZIO.CODICE,ISTANZE LEFT OUTER JOIN ANAGRAFE IST_AZIENDA ON ISTANZE.IDCOMUNE=IST_AZIENDA.IDCOMUNE  AND ISTANZE.CODICETITOLARELEGALE=IST_AZIENDA.CODICEANAGRAFE,CONCESSIONITIPI,ANAGRAFE TITOLARE,CONCESSIONICAUSALI CAUS_ATTUALE,ANAGRAFE IST_RICHIEDENTE,MERCATI,MERCATI_USO WHERE AUTORIZZAZIONI.IDCOMUNE = AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE AND AUTORIZZAZIONI.ID = AUTORIZZAZIONI_CONCESSIONI.FK_IDAUT_ATTUALE AND CONCESSIONITIPI.TIPOCONCESSIONE = AUTORIZZAZIONI_CONCESSIONI.FK_TIPOCONCESSIONE AND TITOLARE.IDCOMUNE = AUTORIZZAZIONI.IDCOMUNE AND TITOLARE.CODICEANAGRAFE = AUTORIZZAZIONI.FK_CODICEANAGRAFE AND CAUS_ATTUALE.IDCOMUNE = AUTORIZZAZIONI.IDCOMUNE AND CAUS_ATTUALE.CODICECAUSALE = AUTORIZZAZIONI.FK_CAUSALE_ACQUISIZIONE AND ISTANZE.IDCOMUNE = AUTORIZZAZIONI.IDCOMUNE AND ISTANZE.CODICEISTANZA = AUTORIZZAZIONI.FKIDISTANZA AND IST_RICHIEDENTE.IDCOMUNE = ISTANZE.IDCOMUNE AND IST_RICHIEDENTE.CODICEANAGRAFE = ISTANZE.CODICERICHIEDENTE AND MERCATI.IDCOMUNE = AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE AND MERCATI.CODICEMERCATO = AUTORIZZAZIONI_CONCESSIONI.FK_CODICEMERCATO AND MERCATI_D.IDCOMUNE = AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE AND MERCATI_D.IDPOSTEGGIO = AUTORIZZAZIONI_CONCESSIONI.FK_IDPOSTEGGIO AND MERCATI_USO.IDCOMUNE = AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE AND MERCATI_USO.ID = AUTORIZZAZIONI_CONCESSIONI.FK_IDMERCATIUSO UNION SELECT AUTORIZZAZIONI_SUBENTRI.IDCOMUNE,AUTORIZZAZIONI_SUBENTRI.FK_CAUSALE_ACQUISIZIONE AS ICONC_CODICECAUSALE,AUTORIZZAZIONI_SUBENTRI.DATA_CESSAZIONE AS DATA_STORICO,ISTANZE.SOFTWARE,ISTANZE.CODICEISTANZA AS IST_CODICEISTANZA,ISTANZE.NUMEROISTANZA AS IST_NUMEROISTANZA,ISTANZE.CODICERICHIEDENTE AS IST_CODICERICHIEDENTE,AUTORIZZAZIONI_SUBENTRI.ID AS CONC_ID,AUTORIZZAZIONI_SUBENTRI.AUTORIZNUMERO AS CONC_NUMERO,AUTORIZZAZIONI_SUBENTRI.AUTORIZDATA AS CONC_DATARILASCIO,AUTORIZZAZIONI_SUBENTRI.AUTORIZDATA AS DATARILASCIO,AUTORIZZAZIONI_CONCESSIONI.DATASCADENZA AS CONC_DATASCADENZA,AUTORIZZAZIONI_CONCESSIONI.FK_TIPOCONCESSIONE AS CONC_CODICETIPO,CONCESSIONITIPI.DESCRIZIONE AS CONC_TIPO,AUTORIZZAZIONI_CONCESSIONI.STAGIONALEA AS CONC_STAGIONALEA,AUTORIZZAZIONI_CONCESSIONI.STAGIONALEDA AS CONC_STAGIONALEDA,0 AS CONC_ATTIVA,AUTORIZZAZIONI_SUBENTRI.FK_CODICEANAGRAFE AS CONC_CODICETITOLARE,CONCAT_WS('',TITOLARE.NOMINATIVO,' ',TITOLARE.NOME) AS CONC_TITOLARE,TITOLARE.CODICEFISCALE AS CONC_TIT_CF,TITOLARE.PARTITAIVA AS CONC_TIT_PIVA,TITOLARE.TIPOANAGRAFE AS CONC_TIT_TIPOANAGRAFE,AUT_COLLEGATA.AUTORIZNUMERO AS AUT_NUMERO,AUT_COLLEGATA.AUTORIZDATA AS AUT_DATA,AUT_COLLEGATA.AUTORIZDATA,AUT_COLLEGATA.FKIDREGISTRO AS AUT_CODREGISTRO,TIPOLOGIAREGISTRI.TR_DESCRIZIONE AS AUT_REGISTRO,CONCAT_WS('',IST_RICHIEDENTE.NOMINATIVO,' ',IST_RICHIEDENTE.NOME) AS IST_NOMINATIVO,IST_RICHIEDENTE.TIPOANAGRAFE AS IST_RIC_TIPOANAGRAFE,CONCAT_WS('',IST_AZIENDA.NOMINATIVO,' ',IST_AZIENDA.NOME) AS IST_NOMINATIVOAZIENDA,IST_AZIENDA.TIPOANAGRAFE AS IST_AZI_TIPOANAGRAFE,IST_RICHIEDENTE.CODICEFISCALE AS IST_CODICEFISCALE,IST_RICHIEDENTE.PARTITAIVA AS IST_PARTITAIVA,CAUS_ATTUALE.DESCRIZIONE AS ICONC_CAUSALE,AUTORIZZAZIONI_SUBENTRI.FK_CAUSALE_CESSAZIONE AS ICONC_CODICECAUSALESTORICO,CAUS_STORICO.DESCRIZIONE AS ICONC_CAUSALESTORICO,AUTORIZZAZIONI_CONCESSIONI.FK_CODICEMERCATO AS CONC_IDMERCATO,MERCATI.DESCRIZIONE AS CONC_MERCATO,MERCATI.ATTIVO AS MERC_ATTIVO,AUTORIZZAZIONI_CONCESSIONI.FK_IDPOSTEGGIO AS CONC_IDPOSTEGGIO,MERCATI_D.CODICEPOSTEGGIO AS CONC_POSTEGGIO,MERCATI_D.LARGHEZZA AS CONC_POS_LARGHEZZA,MERCATI_D.LUNGHEZZA AS CONC_POS_LUNGHEZZA,MERCATI_D.SUPERFICIE AS CONC_POS_SUPERFICIE,MERCATI_D.FKCODICETIPOSPAZIO AS POST_IDTIPOSPAZIO,POSTEGGITIPOSPAZIO.TIPOSPAZIO AS POST_TIPOSPAZIO,AUTORIZZAZIONI_CONCESSIONI.FK_IDMERCATIUSO AS CONC_IDMERCATIUSO,MERCATI_USO.DESCRIZIONE AS CONC_DESCRIZIONEUSO,MERCATI_USO.PESO AS PESO_MERCATO,MERCATI_USO.FKCODICEUSO AS MERC_IDUSO, MERCATI_D.FKCODICESTRADARIO AS CONC_POS_CODICESTRADARIO FROM AUTORIZZAZIONI_CONCESSIONI LEFT OUTER JOIN AUTORIZZAZIONI AUT_COLLEGATA ON AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE=AUT_COLLEGATA.IDCOMUNE  AND AUTORIZZAZIONI_CONCESSIONI.FK_IDAUT_COLLEGATA=AUT_COLLEGATA.ID,AUTORIZZAZIONI_SUBENTRI LEFT OUTER JOIN TIPOLOGIAREGISTRI ON AUTORIZZAZIONI_SUBENTRI.IDCOMUNE=TIPOLOGIAREGISTRI.IDCOMUNE  AND AUTORIZZAZIONI_SUBENTRI.FKIDREGISTRO=TIPOLOGIAREGISTRI.TR_ID  LEFT OUTER JOIN CONCESSIONICAUSALI CAUS_STORICO ON AUTORIZZAZIONI_SUBENTRI.IDCOMUNE=CAUS_STORICO.IDCOMUNE,CONCESSIONITIPI,ANAGRAFE TITOLARE,CONCESSIONICAUSALI CAUS_ATTUALE,ISTANZE,ANAGRAFE IST_RICHIEDENTE,MERCATI,MERCATI_D,POSTEGGITIPOSPAZIO,MERCATI_USO,ANAGRAFE IST_AZIENDA WHERE AUTORIZZAZIONI_SUBENTRI.IDCOMUNE = AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE AND AUTORIZZAZIONI_SUBENTRI.ID = AUTORIZZAZIONI_CONCESSIONI.FK_IDAUT_ATTUALE AND CONCESSIONITIPI.TIPOCONCESSIONE = AUTORIZZAZIONI_CONCESSIONI.FK_TIPOCONCESSIONE AND TITOLARE.IDCOMUNE = AUTORIZZAZIONI_SUBENTRI.IDCOMUNE AND TITOLARE.CODICEANAGRAFE = AUTORIZZAZIONI_SUBENTRI.FK_CODICEANAGRAFE AND CAUS_ATTUALE.IDCOMUNE = AUTORIZZAZIONI_SUBENTRI.IDCOMUNE AND CAUS_ATTUALE.CODICECAUSALE = AUTORIZZAZIONI_SUBENTRI.FK_CAUSALE_ACQUISIZIONE;

CREATE OR REPLACE ALGORITHM=MERGE VIEW VW_CONCESSIONILISTA AS SELECT IDCOMUNE, SOFTWARE, CONC_ID, CONC_NUMERO, CONC_DATARILASCIO, CONC_DATASCADENZA, CONC_CODICETIPO, CONC_TIPO, CONC_STAGIONALEA, CONC_STAGIONALEDA, CONC_ATTIVA, CONC_CODICETITOLARE, CONC_TITOLARE, CONC_TIT_CF, CONC_TIT_PIVA, CONC_TIT_TIPOANAGRAFE, AUT_NUMERO, AUT_DATA, AUT_CODREGISTRO, AUT_REGISTRO, IST_CODICEISTANZA, IST_NUMEROISTANZA, IST_CODICERICHIEDENTE, IST_NOMINATIVO, IST_CODICEFISCALE, IST_PARTITAIVA, IST_RIC_TIPOANAGRAFE, ICONC_CODICECAUSALE, ICONC_CAUSALE, ICONC_CODICECAUSALESTORICO, ICONC_CAUSALESTORICO, CONC_IDMERCATO, CONC_MERCATO, MERC_ATTIVO, CONC_IDPOSTEGGIO, CONC_POSTEGGIO, CONC_POS_LARGHEZZA, CONC_POS_LUNGHEZZA, CONC_POS_SUPERFICIE, POST_IDTIPOSPAZIO, POST_TIPOSPAZIO, CONC_IDMERCATIUSO, CONC_DESCRIZIONEUSO, PESO_MERCATO, MERC_IDUSO, CONC_POS_CODICESTRADARIO FROM VW_ISTANZECONCESSIONILISTA;

CREATE OR REPLACE ALGORITHM=MERGE VIEW VW_I_ATTIVITACONCESSIONI AS SELECT I_ATTIVITA.ID AS I_IDATTIVITA, VW_CONCESSIONILISTA.IDCOMUNE, VW_CONCESSIONILISTA.SOFTWARE, VW_CONCESSIONILISTA.CONC_ID, VW_CONCESSIONILISTA.CONC_NUMERO, VW_CONCESSIONILISTA.CONC_DATARILASCIO, VW_CONCESSIONILISTA.CONC_DATASCADENZA, VW_CONCESSIONILISTA.CONC_CODICETIPO, VW_CONCESSIONILISTA.CONC_TIPO, VW_CONCESSIONILISTA.CONC_STAGIONALEA, VW_CONCESSIONILISTA.CONC_STAGIONALEDA, VW_CONCESSIONILISTA.CONC_ATTIVA, VW_CONCESSIONILISTA.CONC_CODICETITOLARE, VW_CONCESSIONILISTA.CONC_TITOLARE, VW_CONCESSIONILISTA.CONC_TIT_CF, VW_CONCESSIONILISTA.CONC_TIT_PIVA, VW_CONCESSIONILISTA.CONC_TIT_TIPOANAGRAFE, VW_CONCESSIONILISTA.AUT_NUMERO, VW_CONCESSIONILISTA.AUT_DATA, VW_CONCESSIONILISTA.AUT_CODREGISTRO, VW_CONCESSIONILISTA.AUT_REGISTRO, VW_CONCESSIONILISTA.IST_CODICEISTANZA, VW_CONCESSIONILISTA.IST_NUMEROISTANZA, VW_CONCESSIONILISTA.IST_CODICERICHIEDENTE, VW_CONCESSIONILISTA.IST_NOMINATIVO, VW_CONCESSIONILISTA.IST_CODICEFISCALE, VW_CONCESSIONILISTA.IST_PARTITAIVA, VW_CONCESSIONILISTA.IST_RIC_TIPOANAGRAFE, VW_CONCESSIONILISTA.ICONC_CODICECAUSALE, VW_CONCESSIONILISTA.ICONC_CAUSALE, VW_CONCESSIONILISTA.ICONC_CODICECAUSALESTORICO, VW_CONCESSIONILISTA.ICONC_CAUSALESTORICO, VW_CONCESSIONILISTA.CONC_IDMERCATO, VW_CONCESSIONILISTA.CONC_MERCATO, VW_CONCESSIONILISTA.MERC_ATTIVO, VW_CONCESSIONILISTA.CONC_IDPOSTEGGIO, VW_CONCESSIONILISTA.CONC_POSTEGGIO, VW_CONCESSIONILISTA.CONC_POS_LARGHEZZA, VW_CONCESSIONILISTA.CONC_POS_LUNGHEZZA, VW_CONCESSIONILISTA.CONC_POS_SUPERFICIE, VW_CONCESSIONILISTA.POST_IDTIPOSPAZIO, VW_CONCESSIONILISTA.POST_TIPOSPAZIO, VW_CONCESSIONILISTA.CONC_IDMERCATIUSO, VW_CONCESSIONILISTA.CONC_DESCRIZIONEUSO, VW_CONCESSIONILISTA.PESO_MERCATO, VW_CONCESSIONILISTA.MERC_IDUSO, VW_CONCESSIONILISTA.CONC_POS_CODICESTRADARIO FROM I_ATTIVITA,  VW_CONCESSIONILISTA,  ISTANZE WHERE ISTANZE.IDCOMUNE = I_ATTIVITA.IDCOMUNE AND ISTANZE.FK_IDI_ATTIVITA = I_ATTIVITA.ID AND VW_CONCESSIONILISTA.IDCOMUNE = ISTANZE.IDCOMUNE AND VW_CONCESSIONILISTA.IST_CODICEISTANZA = ISTANZE.CODICEISTANZA;

CREATE OR REPLACE ALGORITHM=MERGE VIEW VW_SCADENZARIO AS
  SELECT VW_BATCH_SCADENZARIO.IDCOMUNE                      AS IDCOMUNE,
    VW_BATCH_SCADENZARIO.ID                                 AS CODICESCADENZA,
    VW_BATCH_SCADENZARIO.SOFTWARE                           AS software,
    VW_BATCH_SCADENZARIO.CODICEISTANZA                      AS codiceistanza,
    ISTANZE.NUMEROPROTOCOLLO                                AS numeroprotocollo,
    ISTANZE.DATAPROTOCOLLO                                  AS dataprotocollo,
    ISTANZE.NUMEROISTANZA                                   AS NUMEROISTANZA,
    ISTANZE.CHIUSURA                                        AS CODSTATOISTANZA,
    STATIISTANZA.STATO                                      AS DESCRSTATOISTANZA,
    VW_BATCH_SCADENZARIO.CODICEMOVIMENTO                    AS CODMOVIMENTO,
    VW_BATCH_SCADENZARIO.DESCRMOVIMENTO                     AS DESCRMOVIMENTO,
    DATE_FORMAT(MOVIMENTI.DATA,_utf8'%d/%m/%Y')                    AS DATAMOVIMENTO,
    VW_BATCH_SCADENZARIO.TIPOMOVIMENTODAFARE                AS CODMOVIMENTODAFARE,
    VW_BATCH_SCADENZARIO.DESCRMOVIMENTODAFARE               AS DESCRMOVIMENTODAFARE,
    DATE_FORMAT(VW_BATCH_SCADENZARIO.DATASCADENZA,_utf8'%d/%m/%Y') AS DATASCADENZASTR,
    VW_BATCH_SCADENZARIO.codiceinventario                   AS codiceinventario,
    VW_BATCH_SCADENZARIO.CODICEAMMINISTRAZIONE              AS CODICEAMMINISTRAZIONE,
    RESPONSABILI.RESPONSABILE                               AS RESPONSABILE,
    INVENTARIOPROCEDIMENTI.PROCEDIMENTO                     AS PROCEDIMENTO,
    TIPIPROCEDURE.PROCEDURA                                 AS PROCEDURA,
    SOFTWARE.DESCRIZIONE                                    AS MODULOSOFTWARE,
    amministrazioni.AMMINISTRAZIONE                         AS AMM_amministrazione,
    AMMINISTRAZIONI.PARTITAIVA                              AS AMM_PARTITAIVA,
    AMMINISTRAZIONI.PASSWORD                                AS AMM_PASSWORD,
    CONCAT_WS(' ',ANAGRAFE.NOMINATIVO, ANAGRAFE.NOME)AS RIC_NOMINATIVO,
    IFNULL(ANAGRAFE.CODICEFISCALE,'') AS RIC_CODICEFISCALE,
    IFNULL(ANAGRAFE.PARTITAIVA,'')    AS RIC_PARTITAIVA,
    ANAGRAFE.INDIRIZZO             AS RIC_INDIRIZZO,
    ANAGRAFE.CAP                   AS RIC_CAP,
    ANAGRAFE.CITTA                 AS RIC_LOCALITA,
    COMUNERESIDENZA.COMUNE         AS RIC_CITTA,
    COMUNERESIDENZA.PROVINCIA      AS RIC_PROVINCIA,
    ANAGRAFE.PASSWORD              AS RIC_PASSWORD,
    CONCAT_WS(' ',TECNICO.NOMINATIVO, TECNICO.NOME) AS TEC_NOMINATIVO,
    IFNULL(TECNICO.CODICEFISCALE,'') AS TEC_CODICEFISCALE,
    IFNULL(TECNICO.PARTITAIVA,'')    AS TEC_PARTITAIVA,
    TECNICO.PASSWORD              AS TEC_PASSWORD,
    CONCAT_WS(' ', AZIENDA.NOMINATIVO, AZIENDA.NOME) AS AZ_NOMINATIVO,
    IFNULL(AZIENDA.CODICEFISCALE,'') AS AZ_CODICEFISCALE,
    IFNULL(AZIENDA.PARTITAIVA,'')    AS AZ_PARTITAIVA,
    AZIENDA.PASSWORD              AS AZ_PASSWORD,
    TIPIMOVIMENTO.FK_FO_SOGGETTIESTERNI
  FROM VW_BATCH_SCADENZARIO
  JOIN ISTANZE ON ISTANZE.IDCOMUNE = VW_BATCH_SCADENZARIO.IDCOMUNE
  AND ISTANZE.CODICEISTANZA = VW_BATCH_SCADENZARIO.CODICEISTANZA
  JOIN RESPONSABILI ON RESPONSABILI.IDCOMUNE = ISTANZE.IDCOMUNE
  AND RESPONSABILI.CODICERESPONSABILE = ISTANZE.CODICERESPONSABILE
  JOIN MOVIMENTI ON MOVIMENTI.IDCOMUNE = VW_BATCH_SCADENZARIO.IDCOMUNE
  AND MOVIMENTI.CODICEMOVIMENTO = VW_BATCH_SCADENZARIO.CODICEMOVIMENTO
  JOIN TIPIMOVIMENTO ON TIPIMOVIMENTO.IDCOMUNE = VW_BATCH_SCADENZARIO.IDCOMUNE
  AND TIPIMOVIMENTO.TIPOMOVIMENTO  = VW_BATCH_SCADENZARIO.TIPOMOVIMENTODAFARE
  JOIN TIPIPROCEDURE ON TIPIPROCEDURE.IDCOMUNE = ISTANZE.IDCOMUNE
  AND TIPIPROCEDURE.CODICEPROCEDURA = ISTANZE.CODICEPROCEDURA
  JOIN SOFTWARE ON SOFTWARE.CODICE = VW_BATCH_SCADENZARIO.SOFTWARE
  JOIN ANAGRAFE ON ANAGRAFE.IDCOMUNE = ISTANZE.IDCOMUNE
  AND ANAGRAFE.CODICEANAGRAFE = ISTANZE.CODICERICHIEDENTE
  JOIN STATIISTANZA ON STATIISTANZA.IDCOMUNE = ISTANZE.IDCOMUNE
  AND STATIISTANZA.SOFTWARE = ISTANZE.SOFTWARE
  AND STATIISTANZA.CODICESTATO = ISTANZE.CHIUSURA
  JOIN AMMINISTRAZIONI ON AMMINISTRAZIONI.IDCOMUNE = VW_BATCH_SCADENZARIO.IDCOMUNE
  AND AMMINISTRAZIONI.CODICEAMMINISTRAZIONE = VW_BATCH_SCADENZARIO.CODICEAMMINISTRAZIONE
  LEFT OUTER JOIN INVENTARIOPROCEDIMENTI ON INVENTARIOPROCEDIMENTI.IDCOMUNE = VW_BATCH_SCADENZARIO.IDCOMUNE
  AND INVENTARIOPROCEDIMENTI.CODICEINVENTARIO = VW_BATCH_SCADENZARIO.CODICEINVENTARIO
  LEFT OUTER JOIN COMUNI COMUNERESIDENZA ON COMUNERESIDENZA.CODICECOMUNE = ANAGRAFE.COMUNERESIDENZA
  LEFT OUTER JOIN ANAGRAFE TECNICO ON TECNICO.IDCOMUNE = ISTANZE.IDCOMUNE
  AND TECNICO.CODICEANAGRAFE = ISTANZE.CODICEPROFESSIONISTA
  LEFT OUTER JOIN ANAGRAFE AZIENDA ON AZIENDA.IDCOMUNE = ISTANZE.IDCOMUNE
  AND AZIENDA.CODICEANAGRAFE = ISTANZE.CODICETITOLARELEGALE;
  
CREATE OR REPLACE ALGORITHM=MERGE VIEW VW_LISTAPRATICHE AS
  SELECT istanze.codicecomune ,
    istanze.idcomune ,
    istanze.software                   AS software ,
    software.descrizionelunga          AS descsoftware ,
    istanze.codiceistanza              AS idpratica ,
    istanze.numeroistanza              AS numeropratica ,
    DATE_FORMAT(istanze.data,'%d/%m/%Y') AS datapresentazione ,
    DATE_FORMAT(istanze.data,'%Y')       AS annopresentazione ,
    DATE_FORMAT(istanze.data,'%m')         AS mesepresentazione ,
    istanze.numeroprotocollo ,
    DATE_FORMAT(istanze.dataprotocollo,'%d/%m/%Y') AS dataprotocollo ,
    istanze.codiceinterventoproc                 AS codiceintervento ,
    vw_alberoproc.sc_descrizione                 AS descrizioneintervento,
    tipiprocedure.codiceprocedura ,
    tipiprocedure.procedura ,
    istanze.lavori        AS oggetto ,
    UPPER(istanze.lavori) AS oggettou ,
    istanze.chiusura      AS codstatopratica ,
    stato                 AS statopratica ,
    responsabili.responsabile ,
    responsabili.telefonolavoro                        AS responsabile_telefono ,
    IFNULL(stradario.codviario,stradario.codicestradario) AS pr_codviario ,
    CONCAT_WS(' ', stradario.prefisso, stradario.descrizione) AS pr_indirizzo ,
    istanzestradario.CODICECIVICO   AS pr_codcivico ,
    istanze.civico                  AS pr_civico ,
    istanze.codicearea              AS codicezonizzazione,
    aree.denominazione              AS zonizzazione ,
    anagrafe.codiceanagrafe         AS CodiceRichiedente ,
    IFNULL(anagrafe.codicefiscale, '') AS codicefiscale ,
    IFNULL(anagrafe.partitaiva, '')    AS partitaiva ,
    CONCAT_WS(' ',anagrafe.nominativo, anagrafe.nome) AS nominativo,
    anagrafe.indirizzo ,
    anagrafe.cap ,
    anagrafe.citta         AS localita ,
    comuneresidenza.comune AS citta ,
    comuneresidenza.provincia ,
    tipisoggetto.tiposoggetto AS tiporapporto ,
    catasto.descrizione       AS tipocatasto ,
    istanzemappali.foglio ,
    istanzemappali.particella ,
    istanzemappali.sub ,
    tecnico.codiceanagrafe AS tec_codice ,
    CONCAT_WS(' ',tecnico.nominativo, tecnico.nome) AS tec_nominativo ,
    IFNULL(tecnico.codicefiscale, '') AS tec_codicefiscale,
    IFNULL(tecnico.partitaiva, '')    AS tec_partitaiva ,
    azienda.codiceanagrafe         AS az_codice ,
    CONCAT_WS(' ',azienda.nominativo, azienda.nome) AS az_nominativo ,
    IFNULL(azienda.codicefiscale, '') AS az_codicefiscale,
    IFNULL(azienda.partitaiva, '')    AS az_partitaiva,
    istruttori.responsabile        AS istruttore,
    istruttori.telefonolavoro      AS istruttore_telefono,
    operatori.responsabile         AS operatore,
    operatori.telefonolavoro       AS operatore_telefono
  FROM 
  istanze 
    join software ON software.codice = istanze.software
    join anagrafe ON anagrafe.idcomune = istanze.idcomune
                      AND anagrafe.codiceanagrafe = istanze.codicerichiedente
    join statiistanza ON statiistanza.idcomune = istanze.idcomune
                          AND statiistanza.software = istanze.software
                          AND statiistanza.codicestato = istanze.chiusura
    join vw_alberoproc ON vw_alberoproc.idcomune = istanze.idcomune
                        AND vw_alberoproc.sc_id = istanze.codiceinterventoproc
    left outer join anagrafe tecnico ON tecnico.idcomune = istanze.idcomune 
                                  AND tecnico.codiceanagrafe = istanze.codiceprofessionista
    left outer join anagrafe azienda ON istanze.idcomune = azienda.idcomune
                                  AND istanze.codicetitolarelegale = azienda.codiceanagrafe
    left outer join istanzestradario ON istanze.idcomune = istanzestradario.idcomune
                                  AND istanze.codiceistanza = istanzestradario.codiceistanza 
                                  AND 1 = istanzestradario.primario
                                  left outer join stradario ON stradario.idcomune = istanzestradario.idcomune
                                                        AND stradario.codicestradario = istanzestradario.codicestradario 
    left outer join istanzemappali ON istanze.idcomune = istanzemappali.idcomune 
                              AND istanze.codiceistanza = istanzemappali.fkcodiceistanza
                              AND 1 = istanzemappali.primario
    left outer join responsabili ON istanze.idcomune = responsabili.idcomune
                            AND istanze.codiceresponsabileproc = responsabili.codiceresponsabile
    left outer join comuni comuneresidenza ON anagrafe.comuneresidenza = comuneresidenza.codicecomune
    left outer join tipisoggetto ON istanze.idcomune = tipisoggetto.idcomune
                                  AND istanze.fkcodicesoggetto = tipisoggetto.codicetiposoggetto
    left outer join aree ON istanze.idcomune = aree.idcomune
                         AND istanze.codicearea = aree.codicearea
    left outer join catasto ON istanzemappali.codicecatasto = catasto.codice
    left outer join tipiprocedure ON istanze.idcomune = tipiprocedure.idcomune
                                  AND istanze.codiceprocedura = tipiprocedure.codiceprocedura
    left outer join responsabili istruttori ON istanze.idcomune = istruttori.idcomune            
                                            AND istanze.codiceistruttore = istruttori.codiceresponsabile
    left outer join responsabili operatori ON operatori.idcomune = istanze.idcomune 
                                            AND operatori.codiceresponsabile = istanze.codiceresponsabile;
